window.QUIZ_ZK_DATA=window.QUIZ_ZK_DATA||{};
window.QUIZ_ZK_DATA["dsa13003"]=[{"id":"dsa13003-pl-P4604294","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"给定一个包含n个数据项的查找表T，若要对表中的某个特定关键字K进行查找，并且T是无序的，则最适合使用的查找方法是（）。","opts":["A. 折半查找","B. 顺序查找","C. 哈希查找","D. 二叉查找树"],"ans":1,"explain":"当查找表是无序表时，可以使用顺序查找方法。"},{"id":"dsa13003-pl-P4604295","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"在评价查找效率时，常用的评价标准是（）。","opts":["A. 查找次数","B. 平均查找长度（ASL）","C. 查找时间（秒）","D. 存储空间占用"],"ans":1,"explain":"在评价查找效率时，需要建立一个评价标准，通常使用平均查找长度（ASL）来衡量。"},{"id":"dsa13003-pl-P4604296","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"顺序查找方法的基本思想是（）。","opts":["A. 从顺序表尾开始向前查找","B. 从顺序表头开始向后逐个比较","C. 使用哈希函数直接定位","D. 依赖于数据在表中的排序"],"ans":1,"explain":"顺序查找方法的基本思想是从顺序表头开始，用给定的目标与表中各记录的关键字值逐个进行比较。"},{"id":"dsa13003-pl-P4604297","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"顺序查找方法的平均查找长度（ASL）在（）情况下达到最大。","opts":["A. 数据有序时","B. 数据无序时","C. 数据完全相等时","D. 数据按查找频率排序时"],"ans":1,"explain":"顺序查找的平均查找长度与顺序表中的记录个数成正比，无论是成功查找还是不成功查找，时间复杂度皆为O(n)。"},{"id":"dsa13003-pl-P4604298","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"折半查找（二分查找）的前提条件是（）。","opts":["A. 数据无序","B. 数据按关键字有序","C. 数据存储在链表中","D. 数据量必须为偶数"],"ans":1,"explain":"折半查找也称为二分查找，其适用条件是数组中各个记录按关键字有序排列。"},{"id":"dsa13003-pl-P4604299","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"折半查找过程中，每次比较后候选区间大小的变化是（）。","opts":["A. 减半","B. 增加","C. 不变","D. 变为原来的1/4"],"ans":0,"explain":"折半查找的每次比较都将遗留的数据排除掉差不多一半（也排除了中间元素）。"},{"id":"dsa13003-pl-P4604300","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"索引顺序查找方法中，关于块与块之间关系的描述，正确的是（）。","opts":["A. 块内必须有序，块间也必须有序","B. 块内必须有序，块间可以无序","C. 块内可以无序，块间必须有序","D. 块内和块间都可以无序"],"ans":2,"explain":"每块中的值可以有序，也可以无序，但块与块之间必须有序。"},{"id":"dsa13003-pl-P4604301","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"在索引顺序查找中，如果索引表较小，通常采用的查找方法是（）。","opts":["A. 顺序查找","B. 二分查找","C. 哈希查找","D. 插值查找"],"ans":0,"explain":"如果索引表较小，也可以使用顺序查找。"},{"id":"dsa13003-pl-P4604302","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"二叉查找树的中序遍历结果是（）。","opts":["A. 任意顺序","B. 递增顺序","C. 递减顺序","D. 无法确定"],"ans":1,"explain":"中序遍历二叉查找树可以得到一个有序序列。因为二叉查找树的定义保证了左子树的关键字小于根结点，根结点的关键字小于右子树，所以中序遍历（左-根-右）的结果必然是递增的。"},{"id":"dsa13003-pl-P4604303","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"在二叉查找树中插入关键字时，新结点的插入位置是（）。","opts":["A. 总是插入到根结点","B. 插入到左子树的最左侧","C. 插入到右子树的最右侧","D. 插入到满足二叉查找树性质的位置"],"ans":3,"explain":"新结点的插入位置即在二叉查找树中查找该值失败时的那个空指针的位置。"},{"id":"dsa13003-pl-P4604304","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"AVL树是一种特殊的二叉查找树，其每个节点的平衡因子定义为（ ）。","opts":["A. 左子树节点数 - 右子树节点数","B. 左子树高度 - 右子树高度","C. 左子树最大深度 - 右子树最小深度","D. 右子树高度 - 左子树高度"],"ans":1,"explain":"在二叉查找树的每个结点中增加一个标记，称为平衡因子，定义为该结点左子树的高度减去右子树的高度。"},{"id":"dsa13003-pl-P4604305","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"在高度为3的AVL树中，最少有（）个结点。","opts":["A. 3","B. 4","C. 5","D. 6"],"ans":1,"explain":"高度为0的AVL树所含有结点个数为0。高度为1的AVL树仅含有1个结点。高度为2的AVL树，一棵子树的高度为1，另一棵子树的高度为0，树中含有的结点个数=1+0+1=2。依此类推。在高度为3的AVL树中，两棵子树的高度分别是2和1，所含结点的个数=2+1+1=4。"},{"id":"dsa13003-pl-P4604306","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"B树是一种多路平衡查找树，其每个节点最多可以包含的子树数目取决于阶数m，请问当m=4时，每个节点最多可以包含（）个关键字。","opts":["A. 2","B. 3","C. 4","D. 5"],"ans":1,"explain":"定义8-4 一棵m阶B树或者为空，或者为满足下列性质的m叉树：（1）树中每个结点至多有m棵子树。（...）对于具有n个关键字的非叶结点，将有n+1棵子树。"},{"id":"dsa13003-pl-P4604307","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"在B树中查找关键字时，其比较次数主要与（）因素有关。","opts":["A. 树的阶数和关键字数目","B. 树的高度和关键字的分布","C. 节点中关键字的数目和树的高度","D. 节点中关键字的数目和树的阶数"],"ans":2,"explain":"从查找过程可以看出，在m阶B树上进行查找时，其比较次数与两个因素有关；第一个因素是结点中关键字的数目（最多m-1个，...）；第二个因素是树的高度。"},{"id":"dsa13003-pl-P4604308","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"哈希方法的主要目的是（）。","opts":["A. 实现数据的有序存储","B. 提高查找效率并允许灵活的数据变动","C. 专门用于解决冲突问题","D. 简化数据插入操作"],"ans":1,"explain":"哈希方法使用的存储结构是数组，它采用特殊的机制存放数据，目的是既方便插入数据，也方便查找数据。"},{"id":"dsa13003-pl-P4604309","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"哈希方法中，当两个不同的关键字通过哈希函数计算得到相同的哈希地址时，称为（）。","opts":["A. 冲突","B. 完美匹配","C. 关键字冗余","D. 哈希失败"],"ans":0,"explain":"若有两个不同的关键字k₁和k₂，即k₁≠k₂，有H(k₁)=H(k₂)=L，则称发生了‘冲突’。"},{"id":"dsa13003-pl-P4604310","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"哈希函数设计的首要原则是（）。","opts":["A. 均匀分布，减少冲突","B. 尽可能长的关键字","C. 哈希表的大小最大化","D. 查找频率最高"],"ans":0,"explain":"构造哈希函数的基本原则是：...（2）均匀分布，减少冲突。"},{"id":"dsa13003-pl-P4604311","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"在除留余数法中，选择（）让p以使得哈希函数值均匀分布。","opts":["A. p应等于哈希表长度m","B. p应小于m的最小素数","C. p应小于等于m的最大素数","D. p可以是m的任意因子"],"ans":2,"explain":"理论分析和试验结果均证明，p应取小于等于表长m的最大素数，这样才能达到使哈希函数值均匀分布的目的。"},{"id":"dsa13003-pl-P4604312","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"哈希表中，若采用开放地址法解决冲突，且哈希表长度为m，当发生冲突时，线性探测法求下一地址的公式是（）。","opts":["A. di+1 = (di + 1) % m","B. di+1 = (di + 2) % m","C. di+1 = (di * 2) % m","D. di+1 = (di - 1) % m"],"ans":0,"explain":"在用线性探测法解决冲突时，求下一地址的公式是：di+1=(di+1)mod m，其中，d₁=H(k)。"},{"id":"dsa13003-pl-P4604313","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"以下（）方法不属于解决哈希冲突的方法。","opts":["A. 开放地址法","B. 链地址法","C. 顺序存储法","D. 桶式哈希法"],"ans":2,"explain":"开放地址法和链地址法作为解决哈希冲突的方法，并提到了桶式哈希法作为开放地址法的一种变体。"},{"id":"dsa13003-pl-P4604314","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"哈希表在查找给定关键字时，（）方法不需要考虑关键字的排序情况。","opts":["A. 顺序查找","B. 二分查找","C. 哈希查找","D. 折半查找"],"ans":2,"explain":"在哈希表中查找某个关键字是最方便的。但查找的关键字根据哈希函数计算存储地址，并不知道关键字的排序情况。"},{"id":"dsa13003-pl-P4604315","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"哈希表的装填因子α越接近于1，（）使得查找的平均查找长度会增大。","opts":["A. 查找成功的平均查找长度","B. 查找失败的平均查找长度","C. 两者都会","D. 两者都不会"],"ans":0,"explain":"当采用开放地址法解决冲突时，平均查找长度不依赖于表的长度n，而只依赖于表的装填因子α。α越接近于1，平均查找长度越大。"},{"id":"dsa13003-pl-P4604393","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"简述哈希查找方法的基本思想，并指出其优点和缺点。","opts":[],"ans":null,"explain":"1.基本思想：哈希查找方法通过哈希函数将关键字映射到表中的某个位置，进而在该位置查找记录。如果发生冲突（即不同关键字映射到同一位置），则通过一定的冲突解决方法（如开放定址法、链地址法等）进行处理。<br/>2.优点：查找速度快，平均查找时间接近常数时间O(1)，特别适合于关键字分布均匀且数据量大的情况。<br/>3.缺点：哈希函数的选取对查找效率有很大影响，且当哈希表装填因子较大时，冲突增多，查找效率下降；哈希表扩容时，需要重新计算所有记录的哈希值并重新插入，开销较大。"},{"id":"dsa13003-pl-P4604394","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"简述折半查找的基本步骤，并说明其优点和缺点。","opts":[],"ans":null,"explain":"1.基本步骤：<br/>确定查找区间的上下界（low和high）。<br/>计算中间位置mid（注意取整）。<br/>将中间位置的关键字与目标进行比较。<br/>如果相等，则查找成功，返回mid。<br/>如果不相等，根据比较结果调整查找区间的上下界，继续在子区间内查找。<br/>重复上述步骤，直到找到目标或查找区间为空。<br/>2.优点：<br/>查找效率高，平均查找长度为O(logn)。<br/>适用于大量数据的有序存储。<br/>3.缺点：<br/>要求数据必须有序存储。<br/>只适用于顺序存储结构，不适用于链表等非线性结构。<br/>插入和删除操作可能会破坏数据的有序性，需要重新排序。"},{"id":"dsa13003-pl-P4604395","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"简述二叉查找树删除结点时的三种情况及处理方法。","opts":[],"ans":null,"explain":"1.度为0（叶结点）：直接删除该结点，其父结点的相应孩子指针置为空。<br/>2.度为1：用该结点的非空子树代替该结点，并调整其父结点的孩子指针指向该子树。<br/>3.度为2：用该结点的中序后继（或前驱）结点代替该结点，并删除中序后继（或前驱）结点。中序后继是右子树中的最小结点（无左子树），中序前驱是左子树中的最大结点（无右子树）。"},{"id":"dsa13003-pl-P4604396","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"简述直接定址法构造哈希函数的特点，并给出一个实际应用场景。","opts":[],"ans":null,"explain":"1.特点：<br/>计算简单：哈希函数是关键字值的线性函数，计算量小。<br/>冲突最少：在合适的场景下，几乎无冲突。<br/>2.实际应用场景：<br/>假设需要统计一个班级（共50人）中每个学生的考试成绩，学生的学号为关键字（1~50）。此时，可以使用直接定址法构造哈希函数，哈希表大小为50，哈希函数为H(k) = k - 1（k为学号），这样可以直接通过学号定位到每个学生的成绩存储位置。"},{"id":"dsa13003-pl-P4604397","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"简述哈希表查找效率的两个主要度量指标，并解释它们各自的含义。","opts":[],"ans":null,"explain":"1.查找成功的平均查找长度（ASL成功）：<br/>含义：表示在哈希表中成功查找到某个关键字时，平均需要进行的比较次数。<br/>解析：这个指标反映了哈希表在查找成功时的效率。当哈希函数设计合理且冲突较少时，ASL成功会较小，表示查找效率高。<br/>2.查找失败的平均查找长度（ASL失败）：<br/>含义：表示在哈希表中查找一个不存在的关键字时，平均需要进行的比较次数，直到确定该关键字不在表中。<br/>解析：这个指标反映了哈希表在查找失败时的效率。它依赖于哈希表的装填因子和冲突解决策略。当哈希表较满或冲突较多时，ASL失败会增大，表示查找失败时的效率较低。"},{"id":"dsa13003-pl-P4604357","type":"calc","tier":"创新","conf":"adapt","chap":"第7-8章","q":"阅读以下伪代码，判断其实现的查找算法类型，并简述其查找过程。 Algorithm SequentialSearch(T, K) Input: T is an unordered list of records, K is the target key Output: The index of the record with key K if found, -1 if not found for i from 0 to length(T) - 1 if T[i].key == K return i return -1","opts":[],"ans":null,"explain":"1.算法类型：顺序查找<br/>2.查找过程：从查找表的第一个记录开始，逐个将记录的关键字与目标关键字K进行比较，若找到相等的记录，则返回该记录的位置（索引）；若遍历完所有记录都未找到相等的记录，则返回-1表示查找失败。该算法适用于无序或有序查找表，但效率较低，特别是在数据量大的情况下。"},{"id":"dsa13003-pl-P4604358","type":"calc","tier":"创新","conf":"adapt","chap":"第7-8章","q":"阅读以下顺序查找的算法伪代码，指出其核心步骤，并说明如何修改以支持对关键字值有重复情况的查找。 Algorithm SeqSearch(T, K) Input: T is an array of records, K is the target key Output: The index of the first occurrence of K in T, -1 if not found for i from 0 to length(T) - 1 if T[i].key == K return i return -1","opts":[],"ans":null,"explain":"1.核心步骤：通过for循环遍历数组T，逐个将记录的关键字值与目标关键字K进行比较，若相等则返回当前下标i。<br/>2.修改支持重复查找：<br/>使用一个列表或数组来保存所有等于K的关键字所在的下标。<br/>在发现相等的关键字时，不直接返回，而是将该下标添加到列表中。<br/>遍历完成后，若列表非空，则返回列表中的第一个元素（即第一次出现K的下标）；若列表为空，则返回-1。"},{"id":"dsa13003-pl-P4604359","type":"calc","tier":"创新","conf":"adapt","chap":"第7-8章","q":"设计一个算法，实现索引顺序查找，要求算法能够处理任意给定的关键字和已分块且块间有序的数据集（假设块内数据无序），并返回查找结果（成功则返回关键字在数据集中的位置，失败则返回-1）。","opts":[],"ans":null,"explain":"1.建立索引表：遍历所有块，记录每个块的最大值，并存储其对应的块位置或索引，构建索引表。<br/>2.查找索引表：在索引表中，使用顺序查找或二分查找（取决于索引表大小）找到第一个大于或等于查找关键字的索引项。<br/>3.块内查找：在索引项指向的块内，使用顺序查找查找关键字。<br/>4.返回结果：如果找到关键字，则返回其在数据集中的位置；如果未找到，则返回-1。"},{"id":"dsa13003-pl-P4604360","type":"calc","tier":"创新","conf":"adapt","chap":"第7-8章","q":"阅读AVL树插入操作的描述，回答以下问题： 1.当AVL树因插入新节点而失平衡时，需要找到哪个节点进行旋转？ 2.描述RR型旋转的具体过程。","opts":[],"ans":null,"explain":"1.当AVL树因插入新节点而失平衡时，需要找到哪个节点进行旋转？<br/>距新插入节点最近的失平衡节点。<br/>2.描述RR型旋转的具体过程。<br/>   找到失平衡的节点v和其右孩子节点w。<br/>   让w升为v的父节点，v成为w的左孩子节点。<br/>   将w原来的左子树T₂转移给v，作为其右子树。<br/>   其他两棵子树T₁和T₃保持不变。"},{"id":"dsa13003-pl-P4604483","type":"fill","tier":"拔高","conf":"adapt","chap":"第7-8章","q":"顺序查找方法的空间复杂度为__1__。","opts":[],"ans":["O(1)"],"explain":"SeqSearch需要的空间并不依顺序表的元素个数的变化而变化，空间复杂度为O(1)。\n参考答案: A.O(1)"},{"id":"dsa13003-pl-P4604484","type":"fill","tier":"拔高","conf":"adapt","chap":"第7-8章","q":"折半查找的平均查找长度与数据量的关系是__1__。","opts":[],"ans":["O(logn)"],"explain":"当查找成功时，折半查找的平均查找长度对n来说是对数级的，即O(logn)。\n参考答案: A.O(logn)"},{"id":"dsa13003-pl-P4604485","type":"fill","tier":"拔高","conf":"adapt","chap":"第7-8章","q":"B树是一种__1__的树，其所有叶节点都出现在__2__上。","opts":[],"ans":["多路平衡查找B.同一层"],"explain":"B树是一种多路平衡查找树”以及“B树的所有叶结点都在同一层中。\n参考答案: A.多路平衡查找B.同一层"},{"id":"dsa13003-pl-P4604486","type":"fill","tier":"拔高","conf":"adapt","chap":"第7-8章","q":"哈希方法的核心是__1__，它决定了数据在哈希表中的存储位置。","opts":[],"ans":["哈希函数"],"explain":"担负计算策略的就是哈希函数，它以关键字值为自变量，得到的值是数组的下标。\n参考答案: A.哈希函数"},{"id":"dsa13003-pl-P4604487","type":"fill","tier":"拔高","conf":"adapt","chap":"第7-8章","q":"哈希表中，哈希函数设计的重要目标是让关键字的哈希地址__1__。","opts":[],"ans":["均匀分布"],"explain":"目的是让一组关键字的哈希地址均匀分布在整个地址空间中，从而减少冲突。\n参考答案: A.均匀分布"},{"id":"dsa13003-pl-P4604265","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"以下关于有向无环图（DAG）的说法，正确的是（）。","opts":["A. DAG图中一定存在回路","B. DAG图可以表示具有层次关系的事件集合","C. DAG图不能用于表示含有公共子表达式的表达式","D. DAG图只能用于表示二叉树"],"ans":1,"explain":"有向无环图可用来表示有先后关系的事件集合。"},{"id":"dsa13003-pl-P4604266","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"拓扑排序是对有向无环图（DAG）进行的一种排序方式，其目的是（）。","opts":["A. 确定图中所有顶点的最短路径","B. 找到一个满足所有边方向的顶点线性序列","C. 检测图中是否存在环","D. 求解图的最大流"],"ans":1,"explain":"有向无环图G=(V，E)的拓扑序列是G中顶点的一个线性序列，并且满足以下关系：对于图G中的所有顶点v和w，如果(v，w)∈E，则在线性序列中，v排在w之前。"},{"id":"dsa13003-pl-P4604267","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"在AOE网中，如果一个活动的最早开始时间和最迟开始时间相等，则这个活动是（）。","opts":["A. 非关键活动","B. 关键活动","C. 任意活动","D. 起始活动"],"ans":1,"explain":"把l(i)=e(i)的活动称作关键活动。"},{"id":"dsa13003-pl-P4604268","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"在Dijkstra算法中，集合S的作用是（）。","opts":["A. 存储已找到最短路径的顶点","B. 存储未找到最短路径的顶点","C. 存储图中所有顶点","D. 存储最短路径上的所有边"],"ans":0,"explain":"S为已找到从源点v₀出发的最短路径的终点集合，其初态只含有源点v₀。"},{"id":"dsa13003-pl-P4604269","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"在Floyd算法中，A(k)[i][j]表示（）。","opts":["A. 从顶点vi到顶点vj的最短路径长度，且路径中不经过顶点vk","B. 从顶点vi到顶点vj的最短路径长度，且路径中可以经过顶点vk","C. 从顶点vi到顶点vj的直接边的权值","D. 从顶点vi到顶点vk再到vj的最短路径长度"],"ans":1,"explain":"A(k)[i][j]表示从顶点vi到顶点vj的中间顶点序号不大于vk的最短路径的长度。"},{"id":"dsa13003-pl-P4604270","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"排序算法中，若某排序算法在执行过程中不改变具有相等关键字值的两个记录的相对次序，则称该排序算法为（ ）。","opts":["A. 不稳定排序","B. 稳定排序","C. 内部排序","D. 外部排序"],"ans":1,"explain":"定义7-2 具有相等关键字的两个记录R₁和R₂，在排序之前，R₁位于R₂之前，在排序之后，R₁仍然位于R₂之前，即排序并没有改变具有相等关键字值的两个记录的相对次序，这样的排序方法称为稳定的。"},{"id":"dsa13003-pl-P4604271","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"若待排序的数据量非常大，不能全部放入内存，需要借助外存完成排序，这种排序称为（ ）。","opts":["A. 稳定排序","B. 不稳定排序","C. 内部排序","D. 外部排序"],"ans":3,"explain":"当待排序的数据量大，全部数据不能同时放在内存中，需要借助外存完成排序过程时，相应的排序称为外部排序或外排序。"},{"id":"dsa13003-pl-P4604272","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"在直接插入排序中，当待排序序列已经是非递减有序时，其时间复杂度为（）。","opts":["A. O(n²)","B. O(n log n)","C. O(n)","D. O(log n)"],"ans":2,"explain":"当待排序序列中记录按关键字非递减有序排列时，要插入的记录只需要和前一位置的记录进行比较，并且不发生交换，总的交换次数为0。这是直接插入排序算法能够达到的最优情况。"},{"id":"dsa13003-pl-P4604273","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"直接插入排序的稳定性是（）。","opts":["A. 不稳定","B. 稳定","C. 依赖于具体实现","D. 无法确定"],"ans":1,"explain":"直接插入排序可以保证具有相等关键字值的两个元素在排序前后的相对次序保持不变，即直接插入排序是稳定的。"},{"id":"dsa13003-pl-P4604274","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"希尔排序相比于直接插入排序，其改进的关键在于（）。","opts":["A. 减少了比较次数","B. 减少了移动次数","C. 引入了分组排序机制","D. 使用了归并排序的思想"],"ans":2,"explain":"希尔排序又称缩小增量排序，它是插入排序的一种改进...它采用了一个很巧妙的技巧，即将长数据段划分成短数据段，对短数据段进行直接插入排序，再将这些短数据段逐渐扩成基本有序的长数据段。"},{"id":"dsa13003-pl-P4604275","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"在希尔排序中，选择增量序列的原则通常不包括（）","opts":["A. 增量之间最好是奇数","B. 增量之间不应有倍数关系","C. 增量递减得越快越好","D. 最后一趟的增量必须是1"],"ans":2,"explain":"“增量之间最好不是倍数关系”，并且“最后一趟的增量一定是1”。"},{"id":"dsa13003-pl-P4604276","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"起泡排序算法的基本思想是（）。","opts":["A. 逐趟将待排序记录的关键字按从大到小顺序“归位”","B. 通过快速划分实现快速排序","C. 选择一个元素作为基准，重新排列数组","D. 利用堆结构进行排序"],"ans":0,"explain":"起泡排序算法的一般策略是：扫描整个数组，依次比较相邻的两个元素，如果它们是逆序的，则交换它们，持续地进行这个过程，直到所有元素都有序时为止。"},{"id":"dsa13003-pl-P4604277","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"起泡排序算法在最优情况下的时间复杂度是（）。","opts":["A. O(n log n)","B. O(n²)","C. O(n)","D. O(1)"],"ans":2,"explain":"对于改进的起泡排序算法，当初始数据已有序时，出现最优情况，仅需要一趟扫描即能完成排序任务，时间复杂度为O(n)。"},{"id":"dsa13003-pl-P4604278","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"快速排序算法的主要思想是（）。","opts":["A. 插入排序","B. 冒泡排序","C. 分治策略","D. 堆排序"],"ans":2,"explain":"快速排序算法基于分治思想。"},{"id":"dsa13003-pl-P4604279","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"快速排序中，如果每次划分都非常平衡，其时间复杂度为（）。","opts":["A. O(n)","B. O(nlogn)","C. O(n²)","D. O(logn)"],"ans":1,"explain":"如果每次都能把数组划分成元素个数大致相等的两个子段，则快速排序能达到最优情况，总的时间复杂度为O(nlogn)。"},{"id":"dsa13003-pl-P4604280","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"简单选择排序的时间复杂度是（）。","opts":["A. O(n)","B. O(n log n)","C. O(n²)","D. O(log n)"],"ans":2,"explain":"简单选择排序的时间复杂度为O(n²)。"},{"id":"dsa13003-pl-P4604281","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"简单选择排序中，每趟排序最多需要进行（）数据交换。","opts":["A. n次","B. n-1次","C. 1次","D. 0次"],"ans":2,"explain":"每趟排序最多只需要进行一次数据交换。"},{"id":"dsa13003-pl-P4604282","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"堆排序中，每次从堆中取出的元素是（ ）。","opts":["A. 最小元素","B. 最大元素（在最大堆中）","C. 任意元素","D. 最后一个元素"],"ans":1,"explain":"堆排序也是选择排序的一种。以最大堆为例，最大堆的堆顶元素是全部数据中的最大值，输出这个值，再将剩余元素整理成新的最大堆。"},{"id":"dsa13003-pl-P4604283","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"堆排序的时间复杂度是（ ）。","opts":["A. O(n)","B. O(n log n)","C. O(n²)","D. O(log n)"],"ans":1,"explain":"堆排序的最佳、平均及最差时间复杂度均为O(nlogn)。"},{"id":"dsa13003-pl-P4604284","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"归并排序中，参与二路归并的两个有序序列的长度可以是（）。","opts":["A. 必须相同","B. 必须不同","C. 可以相同或不同","D. 必须是2的幂次"],"ans":2,"explain":"参与二路归并的两个有序序列的长度可以相同，也可以不同。"},{"id":"dsa13003-pl-P4604285","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"归并排序的时间复杂度是（）。","opts":["A. O(n^2)","B. O(nlogn)","C. O(n)","D. O(logn)"],"ans":1,"explain":"归并过程中总共需要复制n个记录，它的时间复杂度为O(n)"},{"id":"dsa13003-pl-P4604286","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"归并排序是一种（）类型的排序算法。","opts":["A. 插入排序","B. 交换排序","C. 选择排序","D. 分治排序"],"ans":3,"explain":"归并排序是一个分治算法。"},{"id":"dsa13003-pl-P4604287","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"在归并排序的非递归实现中，有序段的长度（）。","opts":["A. 每次增加1","B. 每次减少1","C. 每次倍增","D. 每次减半"],"ans":2,"explain":"归并过程中，有序子序列的个数每次减半，而长度倍增。"},{"id":"dsa13003-pl-P4604288","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"盒子排序算法的时间复杂度为（），在给定数据范围内且数据均匀分布的情况下。","opts":["A. O(n^2)","B. O(nlogn)","C. O(n)","D. O(m)"],"ans":2,"explain":"如果初始待排序的元素个数为n，则排序的时间复杂度为O(n)。"},{"id":"dsa13003-pl-P4604289","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"盒子排序算法的空间复杂度主要取决于（）。","opts":["A. 待排序元素的个数n","B. 待排序元素的最大值m","C. 待排序元素的最小值","D. 排序算法的实现方式"],"ans":1,"explain":"待排序整数的大小范围决定了数组的大小。如果n个数据的取值范围是1~m，而m&gt;&gt;n，则需要分配含m个元素的数组"},{"id":"dsa13003-pl-P4604290","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"基数排序的时间复杂度主要取决于（）。","opts":["A. 数据的初始顺序","B. 数据的个数n","C. 数据的位数d","D. 数据的进制r"],"ans":2,"explain":"基数排序一共进行d趟分配和收集，每趟收集需要将r个盒子中的关键字收集起来。因为在每趟排序中，每个数据都被处理两次，所以，算法的时间复杂度可以粗略地认为是O(d×n)。"},{"id":"dsa13003-pl-P4604291","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"基数排序算法的空间复杂度是（）。","opts":["A. O(1)","B. O(n)","C. O(n^2)","D. O(nlogn)"],"ans":1,"explain":"总的空间复杂度为O(n)。"},{"id":"dsa13003-pl-P4604292","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"（）算法的平均情况时间复杂度最优，且在n很大时，性能依然出色。","opts":["A. 快速排序","B. 归并排序","C. 堆排序","D. 希尔排序"],"ans":1,"explain":"如果考虑平均时间复杂度，则快速排序算法的性能最好，归并排序次之，堆排序更次之，特别是当待排序数据量n很大时，归并排序优于堆排序。"},{"id":"dsa13003-pl-P4604293","type":"sc","tier":"基础","conf":"adapt","chap":"第7-8章","q":"以下（）算法是稳定的，且其时间复杂度为O(nlogn)。","opts":["A. 快速排序","B. 堆排序","C. 归并排序","D. 希尔排序"],"ans":2,"explain":"归并排序和基数排序，它们的时间复杂度分别是O(nlogn)和O(dn)，并且都是稳定的排序方法。"},{"id":"dsa13003-pl-P4604384","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"简述拓扑排序的两种实现策略及其基本步骤。","opts":[],"ans":null,"explain":"1.广度优先搜索策略：<br/>初始化：记录所有顶点的入度。<br/>选择并输出：选择一个入度为0的顶点输出。<br/>更新入度：将该顶点的所有直接后继顶点的入度减1。<br/>重复：重复步骤2和3，直到所有顶点都被输出或无法找到入度为0的顶点（表示图中存在环）。<br/>2.深度优先搜索策略：<br/>深度搜索：对图进行深度优先搜索，但在回溯时才输出顶点。<br/>逆序输出：将DFS过程中输出的顶点序列逆序，得到拓扑序列。"},{"id":"dsa13003-pl-P4604385","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"简述关键路径的定义及其重要性。","opts":[],"ans":null,"explain":"1.定义：在AOE网中，从源点到汇点的最长路径称为关键路径，关键路径上的所有活动称为关键活动。<br/>2.重要性：关键路径决定了整个工程的最短完成时间。任何关键活动的推延都将直接导致整个工程的推延，而提前完成非关键活动并不能加快整个工程的进度。"},{"id":"dsa13003-pl-P4604386","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"请简述Dijkstra算法的基本思想。","opts":[],"ans":null,"explain":"Dijkstra算法的基本思想是将图中的顶点分为两个集合：S（已求出最短路径的顶点集合）和V-S（尚未确定最短路径的顶点集合）。算法从源点开始，逐步将V-S中的顶点加入到S中，每次选择V-S中距离源点最近的顶点加入S，并更新V-S中顶点到源点的最短路径长度，直到S包含所有可达的顶点。"},{"id":"dsa13003-pl-P4604387","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"请简述排序算法的时间复杂度主要考量哪些方面。","opts":[],"ans":null,"explain":"1.最优时间复杂度：在所有情况下，执行次数最少的情形的时间复杂度。<br/>2.最差时间复杂度：在所有情况下，执行次数最多的情形的时间复杂度。<br/>3.平均时间复杂度：在所有情况下，平均情况下的执行次数。在不引起歧义的情况下，排序算法的时间复杂度通常指其平均时间复杂度。"},{"id":"dsa13003-pl-P4604388","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"简述直接插入排序的基本思想和优化策略。","opts":[],"ans":null,"explain":"1.基本思想：<br/>初始时，认为第一个元素是有序的，其余元素为无序的。<br/>从第二个元素开始，依次将每个元素插入到它前面已经排序的序列中的适当位置，以保证该元素插入后，插入位置之前的序列仍然有序。<br/>重复这个过程，直到最后一个元素被插入，排序完成。<br/>2.优化策略：<br/>减少数据移动次数：将待排序元素保存在临时变量中，通过元素后移为待排序元素腾出空间，最后再将临时变量中的元素放到正确的位置上。<br/>利用折半查找：在每趟排序中，采用折半查找法找到待排序元素应插入的位置，以减少比较次数，但这将转换为折半插入排序。"},{"id":"dsa13003-pl-P4604389","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"简单选择排序在什么情况下交换次数最少？并简述其特点。","opts":[],"ans":null,"explain":"1.交换次数最少情况：当待排序序列已经是有序的（包括升序或降序）时，交换次数最少，为0次。<br/>2.特点：<br/>比较次数固定：无论初始序列如何，简单选择排序的比较次数都是固定的，为n(n-1)/2，即1到n-1的累加和。<br/>交换次数少：相对于其他排序算法，简单选择排序的交换次数较少，每趟最多只交换一次。<br/>不稳定：由于可能发生不相邻元素的交换，因此简单选择排序是不稳定的排序算法。"},{"id":"dsa13003-pl-P4604390","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"简述归并排序递归实现的基本步骤。","opts":[],"ans":null,"explain":"1.划分：将待排序数组从中间位置一分为二，得到两个子数组。<br/>2.递归：对两个子数组分别进行递归的归并排序。<br/>3.归并：当子数组的长度为1时，认为它已经是有序的，不再递归。此时，将相邻的有序子数组合并为一个有序数组。<br/>4.继续：重复上述过程，直到整个数组被合并为一个有序数组。"},{"id":"dsa13003-pl-P4604391","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"基数排序是如何通过“分配”和“收集”过程来实现排序的。","opts":[],"ans":null,"explain":"1.分配：根据当前数位的值，将待排序的数据分配到不同的盒子（通常是数组中的一段空间）中。<br/>2.收集：将各个盒子中的数据按照分配时的顺序收集起来，形成新的数据序列。<br/>3.重复：对更高位的数位重复上述分配和收集过程，直到最高位。"},{"id":"dsa13003-pl-P4604392","type":"sa","tier":"创新","conf":"adapt","chap":"第7-8章","q":"简述在什么情况下，简单插入排序的性能会优于快速排序。","opts":[],"ans":null,"explain":"1.数据量较小。<br/>2.数据基本有序。"},{"id":"dsa13003-pl-P4604345","type":"calc","tier":"创新","conf":"adapt","chap":"第5-6章","q":"阅读以下基于广度优先搜索策略的拓扑排序算法伪代码，并回答问题。 function topologicalSortBFS(graph): // 假设graph是以邻接表形式存储的有向图 // 初始化入度表 inDegrees = [0] * numVertices(graph) for each vertex in graph: for each edge (v, w) in vertex.adjList: inDegrees[w] += 1 // 初始化队列，将入度为0的顶点加入队列 queue = [] for i from 0 to numVertices(graph) - 1: if inDegrees[i] == 0: queue.enqueue(i) topologicalOrder = [] while not queue.isEmpty(): vertex = queue.dequeue() topologicalOrder.append(vertex) for each edge (vertex, w) in graph[vertex].adjList: inDegrees[w] -= 1 if inDegrees[w] == 0: queue.enqueue(w) if len(topologicalOrder) != numVertices(graph): return &quot;Graph has a cycle&quot; return topologicalOrder 1.算法中inDegrees数组的作用是什么？ 2.算法中queue队列的作用是什么？ 3.当算法返回“Graph has a cycle”时，表示什么？","opts":[],"ans":null,"explain":"1.inDegrees数组用于记录图中每个顶点的入度，即有多少条边指向该顶点。<br/>2.queue队列用于存储当前入度为0的顶点，以便按拓扑顺序输出。<br/>3.当算法返回“Graph has a cycle”时，表示输入的图不是一个有向无环图，图中存在回路"},{"id":"dsa13003-pl-P4604346","type":"calc","tier":"创新","conf":"adapt","chap":"第5-6章","q":"阅读以下算法描述，简述其主要步骤。 1.输入e条弧(j，k)，建立AOE网的存储结构。 2.从源点v₁出发，令ve(1)=0，按拓扑序列求其余各顶点（事件）的最早发生时间ve(i)（2≤i≤n）。 3.若拓扑序列中顶点个数小于AOE网中顶点数n，则算法终止；否则继续。 4.从汇点vn出发，令vl(n)=ve(n)，按逆拓扑序列求其余各顶点（事件）的最迟发生时间vl(i)(n-1≥i≥1)。 5.根据各顶点（事件）的ve和vl值，求每条弧（活动）的最早开始时间e(s)和最迟开始时间l(s)。 6.若某条弧（活动）满足条件e(s)=l(s)，则为关键活动。","opts":[],"ans":null,"explain":"1.建立AOE网。<br/>2.拓扑排序求最早开始时间。<br/>3.检查是否存在环。<br/>4.逆拓扑排序求最迟开始时间。<br/>5.计算活动的最早和最迟开始时间。<br/>6.辨别关键活动。"},{"id":"dsa13003-pl-P4604347","type":"calc","tier":"创新","conf":"adapt","chap":"第5-6章","q":"设计一个算法，用于求解给定AOE网中的关键路径。","opts":[],"ans":null,"explain":"1.输入：e条弧(j，k)及其持续时间，建立AOE网的存储结构。<br/>2.拓扑排序求ve：<br/>初始化ve(1)=0，其余ve(i)设为无穷大。<br/>创建一个队列，将源点入队。<br/>当队列非空时，取出一个顶点j，遍历所有以j为尾的弧(i，j)，更新ve(j)=max{ve(i)+dut(i，j)}。<br/>如果ve(j)被更新且j未访问过，则将j入队并标记为已访问。<br/>3.检查环：<br/>如果拓扑排序得到的顶点数小于AOE网中顶点数n，则存在环，算法终止。<br/>4.逆拓扑排序求vl：<br/>初始化vl(n)=ve(n)，其余vl(i)设为ve(n)。<br/>创建一个队列，将汇点入队。<br/>当队列非空时，取出一个顶点j，遍历所有以j为头的弧(j，k)，更新vl(j)=min{vl(k)-dut(j，k)}。<br/>如果vl(j)被更新且j未访问过（逆拓扑排序中可能需要其他标记方法，因为节点可能多次入队），则将j入队并标记为已访问（注意逆拓扑排序中的访问标记与拓扑排序不同）。<br/>5.计算活动e(s)和l(s)：<br/>遍历所有弧(j，k)，计算e(s)=ve(j)，l(s)=vl(k)-dut(j，k)。<br/>6.辨别关键活动：<br/>遍历所有活动，若e(s)=l(s)，则标记为关键活动。<br/>7.输出：输出关键路径上的活动。"},{"id":"dsa13003-pl-P4604348","type":"calc","tier":"创新","conf":"adapt","chap":"第5-6章","q":"分析Floyd算法的核心部分，即三重循环的作用。","opts":[],"ans":null,"explain":"从A(0)[i][j]出发，逐次计算从顶点vi到顶点vj的中间顶点序号不大于k（1≤k≤n）的最短路径的长度，即在A(k-1)的基础上计算A(k)，递推地产生一个矩阵序列：A(0)，A(1)，…，A(k)，…，A(n)。"},{"id":"dsa13003-pl-P4604349","type":"calc","tier":"创新","conf":"adapt","chap":"第7-8章","q":"请简述希尔排序中增量选择对排序性能的影响，并指出一个合适的增量选择策略。","opts":[],"ans":null,"explain":"1.增量选择对排序性能有显著影响。增量递减得快，则扫描趟数少，但每趟比较和移动操作多；增量递减得慢，则每趟操作少，但扫描趟数多。<br/>2.一个合适的增量选择策略应平衡这两方面，既不过多增加扫描趟数，也不过多增加每趟的操作量。常用的增量序列包括自然数序列的某种变形，如Hibbard增量序列（形如2^k-1）、Sedgewick增量序列等。增量之间最好不是倍数关系，以避免重复比较。"},{"id":"dsa13003-pl-P4604350","type":"calc","tier":"创新","conf":"adapt","chap":"第7-8章","q":"在平均情况下，记录交换的次数约为最差情况下交换次数的一半","opts":[],"ans":null,"explain":"1.无交换提前终止：在某一趟扫描中，如果没有发生任何数据交换，说明序列已经有序，可以提前终止排序。因为后续扫描也不会再发生交换。<br/>2.记录有序位置确定：记录每趟排序时进行交换的记录的最后位置，这个位置之后的所有元素已经处于最终排序位置，后续扫描时可以不再比较这些元素。"},{"id":"dsa13003-pl-P4604351","type":"calc","tier":"创新","conf":"adapt","chap":"第7-8章","q":"设计一个非递归版本的快速排序算法。","opts":[],"ans":null,"explain":"1.初始化：创建一个栈来模拟递归调用，将初始数组的起始和结束下标压入栈中。<br/>2.循环处理：当栈不为空时，弹出栈顶元素作为当前处理区间的起始和结束下标（left, right）。<br/>3.划分：在当前区间内执行划分操作，得到枢轴的最终位置pivotIndex。<br/>4.入栈：如果pivotIndex左侧还有元素（left &lt; pivotIndex-1），将left和pivotIndex-1作为新的区间压入栈中。<br/>如果pivotIndex右侧还有元素（pivotIndex+1 &lt; right），将pivotIndex+1和right作为新的区间压入栈中。<br/>5.重复：回到第2步，继续处理栈中的区间，直到栈为空。"},{"id":"dsa13003-pl-P4604352","type":"calc","tier":"创新","conf":"adapt","chap":"第7-8章","q":"阅读以下关于堆排序的算法描述，回答问题： 1. 建立初始堆（最大堆） 2. 重复以下步骤直到堆为空： A.取出堆顶元素（最大值），放到数组末尾 B.减小堆的大小（即最后一个有效元素向前移动） C.重新调整堆（整堆），保证堆顶元素仍是当前最大 问题： 1.堆排序的第一步是什么？ 2.堆排序过程中，如何保持堆的特性？ 3.堆排序完成后，数组中的元素顺序是怎样的？","opts":[],"ans":null,"explain":"1.建立初始堆（最大堆）。                                                                 2.通过整堆（调整堆）保持堆的特性。                    3.数组中的元素顺序是升序的（如果建立的是最大堆）。"},{"id":"dsa13003-pl-P4604353","type":"calc","tier":"创新","conf":"adapt","chap":"第7-8章","q":"阅读以下关于归并排序中两个有序序列合并操作的描述，回答问题： 设数组A中依次保存两个递增有序序列，它们的数据元素分别是a₁，a₂，…，am和b₁，b₂，…，bn。使用数组B保存合并后的数据。请简述归并操作的过程，并指出每一步的关键操作。","opts":[],"ans":null,"explain":"1.初始化指针：设置i=0，j=m，k=0，分别指向两个有序序列的起始位置和结果数组B的起始位置。<br/>2.比较并复制：比较A[i]和A[j]（注意A[j]实际上是b₁，因为j从m开始，即第二个序列的起始位置），将较小的元素复制到B[k]，并移动对应的指针（i或j）和k。<br/>3.处理剩余元素：当其中一个序列的元素全部复制到B后，将另一个序列中剩余的所有元素依次复制到B中。<br/>4.结束：此时，B中保存了合并后的有序序列。"},{"id":"dsa13003-pl-P4604354","type":"calc","tier":"创新","conf":"adapt","chap":"第7-8章","q":"阅读盒子排序算法的描述，回答以下问题： 1.盒子排序算法的核心思想是什么？ 2.如果待排序数据中存在重复元素，应如何修改盒子排序算法？ 3.盒子排序算法在哪些情况下不适用？","opts":[],"ans":null,"explain":"1.盒子排序算法的核心思想是利用一个数组（盒子）来记录每个数字出现的次数，然后根据数字出现的次数和顺序来输出排序结果。<br/>2.如果待排序数据中存在重复元素，应将“count[d]=1”修改为“count[d]++”，以记录每个数字出现的次数。<br/>3.盒子排序算法在以下情况下不适用：<br/>    待排序的数据类型无法直接映射为数组下标（如字符串）。<br/>    待排序数据的取值范围远大于数据个数，导致空间复杂度过高。<br/>    需要稳定的排序结果时（盒子排序可能改变相同元素的相对顺序）。"},{"id":"dsa13003-pl-P4604355","type":"calc","tier":"创新","conf":"adapt","chap":"第7-8章","q":"设计基数排序算法的基本步骤，并简述每步的作用。","opts":[],"ans":null,"explain":"1.确定最大位数：遍历所有待排序数据，找出最大数的位数d。<br/>作用：确定需要进行的分配和收集的趟数。<br/>2.初始化计数数组：根据数据的进制r（通常为10），初始化一个大小为r的计数数组count，用于记录每趟分配时每个盒子中的数据个数。<br/>作用：记录分配结果，用于确定每个盒子在收集数组中的位置。<br/>3.分配与收集：从最低位开始，对每位进行分配和收集。<br/>分配：遍历待排序数据，根据当前位的值，将每个数据分配到相应的盒子中，并更新count数组。<br/>收集：根据count数组的信息，将盒子中的数据依次收集到新的数组中，完成一趟排序。<br/>4.重复分配与收集：对更高位重复步骤3，直到最高位。<br/>作用：通过多趟分配和收集，逐步将数据排序。<br/>5.结果输出：收集完所有位的数据后，新数组中的数据即为排序后的结果。<br/>作用：得到最终的排序结果。"},{"id":"dsa13003-pl-P4604356","type":"calc","tier":"创新","conf":"adapt","chap":"第7-8章","q":"阅读以下代码片段，判断其实现的排序算法类型，并简述其排序过程的主要步骤。 def quick_sort(arr, low, high): if low &lt; high: # Partition the array pi = partition(arr, low, high) # Recursively sort elements before and after partition quick_sort(arr, low, pi - 1) quick_sort(arr, pi + 1, high) def partition(arr, low, high): # Choosing the rightmost element as pivot pivot = arr[high] i = low - 1 for j in range(low, high): # If current element is smaller than or equal to pivot if arr[j] &lt;= pivot: i += 1 arr[i], arr[j] = arr[j], arr[i] arr[i + 1], arr[high] = arr[high], arr[i + 1] return (i + 1) # Example usage arr = [10, 7, 8, 9, 1, 5] quick_sort(arr, 0, len(arr) - 1) print(&quot;Sorted array is:&quot;, arr)","opts":[],"ans":null,"explain":"实现的排序算法类型是快速排序。<br/>主要步骤：<br/>1.选择一个元素作为基准（pivot）。<br/>2.重新排列数组，所有比基准值小的元素摆放在基准前面，所有比基准值大的元素摆在基准的后面（相同的数可以到任一边）。在这个分区退出之后，该基准就处于数组的中间位置。这个称为分区（partition）操作。<br/>3.递归地（recursive）把小于基准值元素的子数组和大于基准值元素的子数组排序。"},{"id":"dsa13003-pl-P4604465","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-6章","q":"在表达式树中，重复的子表达式会导致存储空间的浪费。使用__1__可以避免这一问题，其中相同的子表达式只存储一次，其他地方通过引用指向它。","opts":[],"ans":["有向无环图（DAG）"],"explain":"将图6-19进行修改，去掉重复部分，得到图6-20，它是一个有向无环图。从图6-20中可以看出，表达式中相同的子表达式在图中只画了一次，避免了在有向树中的重复出现”，因此答案为“有向无环图（DAG）。\n参考答案: A.有向无环图（DAG）"},{"id":"dsa13003-pl-P4604466","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-6章","q":"拓扑排序的过程中，每输出一个顶点，需要将其所有直接后继顶点的__1__减1。","opts":[],"ans":["入度"],"explain":"每当从图中输出一个顶点时，表明该顶点的所有直接后继顶点均少了一个约束，即入度减1。\n参考答案: A.入度"},{"id":"dsa13003-pl-P4604467","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-6章","q":"在AOE网中，从源点到任意顶点vi的最长路径长度称为事件v的__1__。","opts":[],"ans":["最早开始时间"],"explain":"从源点v₁到任意顶点vi的最长路径长度称为事件v的最早开始时间。\n参考答案: A.最早开始时间"},{"id":"dsa13003-pl-P4604468","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-6章","q":"Dijkstra算法中，初始时dist数组中的值__1__设置。","opts":[],"ans":["dist[i] = cost[v₀][vi]（vi ∈ V）"],"explain":"从v₀出发到图中其余各顶点vi的距离为：dist[i] = cost[v₀][vi]（vi ∈ V）。\n参考答案: A.dist[i] = cost[v₀][vi]（vi ∈ V）"},{"id":"dsa13003-pl-P4604469","type":"fill","tier":"拔高","conf":"adapt","chap":"第7-8章","q":"在计算机中，存储介质主要分为__1__和__2__两大类。","opts":[],"ans":["内存B.外存"],"explain":"计算机中存放待排序数据的存储介质不完全一样。存储介质可以分为内存和外存两大类。\n参考答案: A.内存B.外存"},{"id":"dsa13003-pl-P4604470","type":"fill","tier":"拔高","conf":"adapt","chap":"第7-8章","q":"排序算法的主要衡量标准是__1__和__2__，分别用于评估算法在不同情况下的时间开销和空间开销。","opts":[],"ans":["时间复杂度B.空间复杂度"],"explain":"排序算法中的主要操作包括关键字的比较及记录的交换，交换意味着数据的移动。所以，在时间开销上，主要统计执行这两项操作所花费时间的多少。...排序过程中可能需要使用除这个数组以外的其他空间，这就是排序算法的空间开销。\n参考答案: A.时间复杂度B.空间复杂度"},{"id":"dsa13003-pl-P4604471","type":"fill","tier":"拔高","conf":"adapt","chap":"第7-8章","q":"直接插入排序的最差时间复杂度是__1__。","opts":[],"ans":["O(n²)"],"explain":"当待排序记录按关键字递减排列时，因为是逆序排列，所以每个待插入元素都需要移动到有序子序列的最前面，待插入的元素需要和有序子序列中的所有元素相比较，比较的次数最多，n个元素排序时的比较次数为n(n-1)/2，即时间复杂度为O(n²)。\n参考答案: A.O(n²)"},{"id":"dsa13003-pl-P4604472","type":"fill","tier":"拔高","conf":"adapt","chap":"第7-8章","q":"直接插入排序除了原数组空间外，仅需要__1__的空间复杂度。","opts":[],"ans":["O(1)"],"explain":"除原来的数据所占用的数组空间以外，直接插入排序仅需要临时工作单元，所以它的空间复杂度为O(1)。\n参考答案: A.O(1)"},{"id":"dsa13003-pl-P4604473","type":"fill","tier":"拔高","conf":"adapt","chap":"第7-8章","q":"希尔排序的基本思想是先将待排序的记录序列分割成为若干个子序列分别进行__1__排序，待整个序列中的记录“基本有序”时，再对全体记录进行一次直接插入排序。","opts":[],"ans":["直接插入"],"explain":"先把长数据段划分成短数据段，对短数据段进行直接插入排序（利用的是数据量少的特性），再将这些短数据段逐渐扩成基本有序的长数据段，并对长数据段进行直接插入排序。\n参考答案: A.直接插入"},{"id":"dsa13003-pl-P4604474","type":"fill","tier":"拔高","conf":"adapt","chap":"第7-8章","q":"起泡排序算法中，每一趟排序结束后，都会将一个元素放置到其__1__位置上。","opts":[],"ans":["最终"],"explain":"每趟起泡排序都会将一个元素移动到它的最终位置。\n参考答案: A.最终"},{"id":"dsa13003-pl-P4604475","type":"fill","tier":"拔高","conf":"adapt","chap":"第7-8章","q":"起泡排序算法在平均情况下的记录交换次数约为最差情况下交换次数的__1__。","opts":[],"ans":["一半"],"explain":"在平均情况下，记录交换的次数约为最差情况下交换次数的一半。\n参考答案: A.一半"},{"id":"dsa13003-pl-P4604476","type":"fill","tier":"拔高","conf":"adapt","chap":"第7-8章","q":"快速排序算法中，用于分割数据集的元素称为__1__。","opts":[],"ans":["枢轴（或划分元素）"],"explain":"参考答案: A.枢轴（或划分元素）"},{"id":"dsa13003-pl-P4604477","type":"fill","tier":"拔高","conf":"adapt","chap":"第7-8章","q":"快速排序算法的平均时间复杂度为__1__，但在最坏情况下的时间复杂度为__2__。","opts":[],"ans":["O(nlogn)B.O(n²)"],"explain":"“平均情况介于最优与最差之间，在理想状态下，时间复杂度为O(nlogn)”，“在最差情况下，因为每次只能划分出一个枢轴，需要对数组进行n-1趟扫描，时间复杂度为O(n²)”。\n参考答案: A.O(nlogn)B.O(n²)"},{"id":"dsa13003-pl-P4604478","type":"fill","tier":"拔高","conf":"adapt","chap":"第7-8章","q":"简单选择排序中，对于n个元素的数组，共需进行__1__趟排序，每趟排序的比较次数与待排序序列的初始状态__2__。","opts":[],"ans":["n-1B.无关"],"explain":"“对于有n个数据的序列，它共需n-1趟排序”，并且“其比较次数与待排序序列的初始状态无关”。\n参考答案: A.n-1B.无关"},{"id":"dsa13003-pl-P4604479","type":"fill","tier":"拔高","conf":"adapt","chap":"第7-8章","q":"堆排序过程中，堆顶元素被取出后，需要进行的操作是__1__和__2__。","opts":[],"ans":["整堆B.将最后一个元素放到堆顶"],"explain":"参考答案: A.整堆B.将最后一个元素放到堆顶"},{"id":"dsa13003-pl-P4604480","type":"fill","tier":"拔高","conf":"adapt","chap":"第7-8章","q":"归并排序的基本操作是__1__两个有序序列。","opts":[],"ans":["合并"],"explain":"二路归并排序中用到的基本操作就是两个有序序列的合并。\n参考答案: A.合并"},{"id":"dsa13003-pl-P4604481","type":"fill","tier":"拔高","conf":"adapt","chap":"第7-8章","q":"归并排序的时间复杂度是__1__。","opts":[],"ans":["O(nlogn)"],"explain":"归并排序每次二分数组，对于长度为n的数组，二分数组的次数应为logn。因为每一次都需要对数组中所有元素进行一次扫描，所以每次的操作都需要n步，这样，总的时间复杂度为O(nlogn)。\n参考答案: A.O(nlogn)"},{"id":"dsa13003-pl-P4604482","type":"fill","tier":"拔高","conf":"adapt","chap":"第7-8章","q":"盒子排序算法在排序过程中，主要操作是设置数组中某下标位置的元素值，并根据__1__输出相应的下标值。","opts":[],"ans":["元素值"],"explain":"排序过程中，主要操作是设置数组中某下标位置的元素值，并根据元素值输出相应的下标值。\n参考答案: A.元素值"},{"id":"dsa13003-pl-P4604243","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"在最大堆中，任意节点的值与其子节点的值之间的关系是（）。","opts":["A. 小于等于子节点的值","B. 大于等于子节点的值","C. 小于子节点的值","D. 等于子节点的值"],"ans":1,"explain":"式（5-8）中的后一种关系表明，任何一个分支结点的值都不小于它的子结点的值，故树的根结点的值是全部结点中的最大值。这样的堆称为最大堆或大根堆。"},{"id":"dsa13003-pl-P4604244","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"在创建最大堆的过程中，从（）位置的节点开始调整。","opts":["A. 第一个节点","B. 最后一个节点","C. 最后一个分支节点","D. 任意节点"],"ans":2,"explain":"对分支结点从后向前依次进行处理。先选择最后一个分支结点，将以该结点为根的子树整理成堆。"},{"id":"dsa13003-pl-P4604245","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"优先队列的主要特性是（）。","opts":["A. 先进先出","B. 后进先出","C. 优先值决定输出顺序","D. 任意顺序输出"],"ans":2,"explain":"输出时，选择最优先的元素输出。‘最优先’取决于优先值的定义，可以是优先值最小，也可以是优先值最大。"},{"id":"dsa13003-pl-P4604246","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"使用堆结构实现的优先队列，在每次输出最优先元素后，需进行的操作是（）。","opts":["A. 无需操作","B. 插入新元素","C. 重新调整堆结构","D. 删除堆中所有元素"],"ans":2,"explain":"输出堆顶元素即得到优先队列中的最优先元素，优先队列中的剩余元素再重新整理成最大堆，等待下一次的输出。"},{"id":"dsa13003-pl-P4604247","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"在树的存储结构中，若需要快速访问任意结点的所有孩子结点，但不关心父结点的信息，最适合采用的表示法是（）。","opts":["A. 父结点表示法","B. 孩子结点表示法","C. 孩子-兄弟表示法","D. 都不适合"],"ans":1,"explain":"孩子结点表示法可以方便地查找某个结点的所有孩子结点，因为每个结点的所有孩子结点都被组织成一个单链表，头指针存储在结点对应的数组中。这种方式不需要遍历整个数组去查找，因此效率较高。"},{"id":"dsa13003-pl-P4604248","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"在将森林转换为二叉树的过程中，森林中第一棵树的根结点会成为二叉树的（）部分。","opts":["A. 右子树的根结点","B. 左子树的根结点","C. 根的左孩子结点","D. 根的右孩子结点"],"ans":2,"explain":"“规则1：将森林转换成二叉树”中提到，若F非空（m&gt;0），则森林中T₁的根作为二叉树B的根root。因此，森林中第一棵树的根结点会直接成为二叉树的根结点，而不是右子树或左子树的根结点，也不是根的左或右孩子结点。但在实际构建过程中，从逻辑上讲，它是原树（或森林中的第一棵树）的根，转换后它在二叉树中的位置相当于根的左子树的最顶端，即根的左孩子结点（尽管实际上它是二叉树的根）。"},{"id":"dsa13003-pl-P4604249","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"在树的遍历中，如果首先访问根节点，然后依次先序遍历各棵子树，这种遍历方式称为（）。","opts":["A. 中序遍历","B. 后序遍历","C. 先序遍历","D. 层次遍历"],"ans":2,"explain":"（1）先序（根）遍历：先访问树的根结点，再依次先序遍历根结点的各棵子树。"},{"id":"dsa13003-pl-P4604250","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"在计算机中，使用定长编码表示字符时，若每个字符用8位二进制表示，原文包含100个字符，则译文的二进制位数是（）。","opts":["A. 800位","B. 100位","C. 8位","D. 1000位"],"ans":0,"explain":"定长编码在处理时算法简单，效率高，在编码长度确定之后，译文的长度完全取决于原文的长度。比如，当用m位二进制表示一个字符时，若原文含有n个字符，则译文的二进制位数是n×m。"},{"id":"dsa13003-pl-P4604251","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"在给定字符集及各字符的权值后，为了设计具有前缀特性的最短编码方案，应采用的算法是（）。","opts":["A. 快速排序算法","B. 哈夫曼算法","C. 归并排序算法","D. 堆排序算法"],"ans":1,"explain":"构造哈夫曼树的算法是由哈夫曼首先提出的，所以又称为哈夫曼算法。算法可以生成具有前缀特性的最短编码方案。"},{"id":"dsa13003-pl-P4604252","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"在哈夫曼编码中，对于一棵哈夫曼树，其左分支和右分支通常分别标记为（）。","opts":["A. 左分支标记为0，右分支标记为1","B. 左分支标记为1，右分支标记为0","C. 左分支和右分支都标记为0","D. 左分支和右分支都标记为1"],"ans":0,"explain":"在哈夫曼树中，对于所有的分支结点，其左分支标为0，右分支标为1。"},{"id":"dsa13003-pl-P4604253","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"在图G=(V, E)中，若边(u, v)存在，则称顶点u和v互为（）。","opts":["A. 邻接点","B. 弧尾","C. 弧头","D. 父节点"],"ans":0,"explain":"若无向图G中含有边(u, v)，则u和v互为邻接点。"},{"id":"dsa13003-pl-P4604254","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"在图的基本操作中，若想要获取与特定顶点v直接相连的第一个邻接点的下标，应使用的方法是（）。","opts":["A. FirstNeighbor()","B. NextNeighbor()","C. FindVertex()","D. InsertEdge()"],"ans":0,"explain":"定义方法FirstNeighbor( )和NextNeighbor( )，通过这两个方法，可以找到一个顶点的所有邻接点。"},{"id":"dsa13003-pl-P4604255","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"对于含有n个顶点和e条边的无向图，其邻接矩阵中非零元素的个数是（）。","opts":["A. n²","B. n²-e","C. 2e","D. n(n-1)/2"],"ans":2,"explain":"无向图的邻接矩阵是对称矩阵，对于G中的任一条边(vi，vj)，在邻接矩阵中都会对应两个1，即A[i][j]和A[j][i]均为1。所以，图G的邻接矩阵中有2e个1。"},{"id":"dsa13003-pl-P4604256","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"对于一个包含n个顶点和e条边的无向图G，如果采用邻接矩阵来表示该图，则邻接矩阵中非零元素的个数（不考虑对角线元素）与图中边的数量e之间的关系是（）。","opts":["A. 非零元素个数等于e","B. 非零元素个数等于2e","C. 非零元素个数小于e","D. 非零元素个数大于2e"],"ans":1,"explain":"对于无向图G，由于边没有方向性，所以当边(vi, vj)存在时，边(vj, vi)也必定存在。在邻接矩阵中，这表现为A[i][j]和A[j][i]均会被设置为1（对于无权图）或wij（对于带权图）。因此，对于图G中的任一条边(vi, vj)，在邻接矩阵中都会对应两个非零元素（不考虑对角线元素，因为对角线元素表示自环，通常设置为0或特殊值）。所以，无向图的邻接矩阵中非零元素的个数（不考虑对角线元素）等于图中边数量的两倍，即非零元素个数等于2e。"},{"id":"dsa13003-pl-P4604257","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"在邻接表中，如果图G有n个顶点和e条边（无向图），则邻接表中链表的总节点数最多为（）。","opts":["A. n","B. e","C. 2e","D. n+e"],"ans":2,"explain":"对于无向图G₁，使用邻接表可以很方便地求出顶点的度，数组下标为i的元素指向的单链表中结点的个数即顶点vi的度。图G₁共有6条边，由图6-7c可知，对应的邻接表内共有12个表结点，为边数的两倍。"},{"id":"dsa13003-pl-P4604258","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"以下（）代码是VerToNum函数中用于查找顶点u在顶点表verticesList中的下标，并在找到时返回该下标的部分。","opts":["A. int i = 0;","B. while (g.verticesList[i]!=u &amp;&amp; i&lt;getNumVertices(g)) i++;","C. if (i!=getNumVertices(g)) return i;","D. return -1;"],"ans":1,"explain":"VerToNum函数通过循环遍历顶点表verticesList来查找顶点u。循环条件是顶点u不等于当前遍历到的顶点且下标i小于顶点总数getNumVertices(g)。"},{"id":"dsa13003-pl-P4604259","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"在深度优先搜索（DFS）中，为了防止对顶点的重复访问，通常使用（）数据结构来记录顶点的访问状态。","opts":["A. 队列","B. 栈","C. 链表","D. 数组"],"ans":3,"explain":"为了解决重复访问及图的不连通这两个问题，在遍历图的顶点时，对每个顶点增加一个访问标志，标明该结点是否被访问过。可以使用一维数组visited记录图顶点的访问标志，数组元素的个数等于图中顶点的个数。"},{"id":"dsa13003-pl-P4604260","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"深度优先搜索（DFS）过程中，当某个顶点的所有邻接点都已被访问过时，会执行（）操作。","opts":["A. 继续访问下一个顶点","B. 停止搜索","C. 回退到最近被访问过的且仍有未被访问邻接点的顶点","D. 遍历所有顶点"],"ans":2,"explain":"（5）回退到最近被访问过的且仍有未被访问邻接点的顶点u，转到（4）继续；在不能回退时，转到（6）。"},{"id":"dsa13003-pl-P4604261","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"在图的广度优先搜索（BFS）算法中，使用的主要辅助数据结构是（）。","opts":["A. 栈","B. 队列","C. 链表","D. 哈希表"],"ans":1,"explain":"在广度优先搜索过程中，使用一个队列作为辅助存储结构。"},{"id":"dsa13003-pl-P4604262","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"在一个无向连通图中，任何顶点都可以到达图中其他任何顶点，这是（）的特性。","opts":["A. 非连通图","B. 连通图","C. 强连通图（有向图）","D. 有向无环图"],"ans":1,"explain":"在无向连通图中，任何顶点都可以有到达图中其他任何顶点的路径，这正是连通图的连通性所保证的。"},{"id":"dsa13003-pl-P4604263","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"无向连通图的生成树包含的边数最多为（）。","opts":["A. n","B. n-1","C. n+1","D. 2n-1"],"ans":1,"explain":"使含n个顶点的无向图连通的最少边数是n-1，所以生成树中所含的边数必定是n-1。"},{"id":"dsa13003-pl-P4604264","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"在求最小生成树的算法中，普里姆算法（Prim）的特点是（）。","opts":["A. 适用于边稠密的图","B. 适用于边稀疏的图","C. 总是选择权值最大的边","D. 生成的生成树可能不是唯一的"],"ans":0,"explain":"当图是一个边稠密的图时，适合使用普里姆算法来求图的最小生成树。"},{"id":"dsa13003-pl-P4604377","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"简述堆排序的基本思想，并说明其时间复杂度。","opts":[],"ans":null,"explain":"堆排序的基本思想是利用堆这种数据结构所设计的一种排序算法。堆是一个近似完全二叉树的结构，并同时满足堆积的性质：即子节点的键值或索引总是小于（或者大于）它的父节点。                                                                           1.堆排序分为两个主要过程：<br/>1）建堆：将无序序列构建成一个堆，根据升序或降序需求选择最大堆或最小堆。<br/>2）排序：将堆顶元素（最大或最小元素）与末尾元素进行交换，此时末尾元素就是排序后的最大（或最小）元素。然后将剩余n-1个元素重新构建成堆，这样会得到n个元素的次小（或次大）值。如此反复执行，便能得到一个有序序列了。<br/>堆排序的时间复杂度主要由建堆和排序两个过程决定。建堆的时间复杂度为O(n)，排序过程需要遍历n个元素，每次调整堆的时间复杂度为O(log n)，因此总的时间复杂度为O(n log n)。"},{"id":"dsa13003-pl-P4604378","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"简述树转换为二叉树的过程，并给出其主要步骤。","opts":[],"ans":null,"explain":"1.确定转换起点；<br/>2.处理孩子结点；<br/>3.处理兄弟结点；<br/>4.递归转换；<br/>5.调整结构。"},{"id":"dsa13003-pl-P4604379","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"简述哈夫曼树的构造过程及其特点。","opts":[],"ans":null,"explain":"1.构造过程：<br/>初始时，将给定的n个权值分别作为n棵只有根结点的二叉树的根结点，构成集合F。<br/>从F中选出两棵根结点权值最小的树作为左右子树，构造一棵新的二叉树，新树的根结点权值为左右子树根结点权值之和。<br/>将选中的两棵树从F中删除，加入新构造的树。<br/>重复上述过程，直到F中只剩下一棵树，这棵树即为哈夫曼树。<br/>2.特点：<br/>前缀特性：哈夫曼树的编码满足前缀特性，即任何字符的编码都不是其他字符编码的前缀。<br/>最优性：哈夫曼树的WPL（外部带权路径长度）是最小的，即在所有可能的编码树中，哈夫曼树的WPL最短。<br/>非唯一性：对于同一个权值集合，构造的哈夫曼树可能不是唯一的，但它们的WPL相同。<br/>无度为1的结点：哈夫曼树中没有度为1的结点，所有非叶结点都有两个子结点。"},{"id":"dsa13003-pl-P4604380","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"请简述有向图和无向图的主要区别，并举例说明。","opts":[],"ans":null,"explain":"1.方向性：有向图中的边具有方向性，即每条边都从一个顶点指向另一个顶点，形成有向边（或称为弧）。无向图中的边没有方向性，只是表示两个顶点之间的连接关系。<br/>2.表示方式：有向边通常表示为(u, v)，表示从顶点u指向顶点v。无向边则表示为(u, v)或{u, v}，表示顶点u和v之间的连接，不区分方向。<br/>3.度的概念：在有向图中，顶点的度分为出度和入度。出度是指从该顶点出发的边的数量，入度是指指向该顶点的边的数量。无向图中，顶点的度就是与该顶点相关联的边的数量，不区分出度和入度。<br/>4.连通性：有向图的连通性分为强连通和弱连通。强连通要求每对顶点之间都存在双向路径。弱连通则只要求每对顶点之间至少存在一条单向路径（可以是单向的，也可以是反向的）。无向图的连通性则较为简单，只要求任意两个顶点之间都存在路径即可。<br/>5.举例：<br/>有向图：如城市交通网络，道路有方向性，从A地到B地可能不同于从B地到A地（如单行线）。<br/>无向图：如社交网络中的好友关系，两个人互为好友，关系没有方向性。"},{"id":"dsa13003-pl-P4604381","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"简述邻接矩阵表示图的优缺点。","opts":[],"ans":null,"explain":"1.优点：<br/>直观；<br/>易于实现；<br/>支持快速访问。<br/>2.缺点：<br/>空间浪费；<br/>时间复杂度高；<br/>不直观反映稀疏性。"},{"id":"dsa13003-pl-P4604382","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"简述深度优先搜索（DFS）的基本步骤。","opts":[],"ans":null,"explain":"1.选择图中任意指定的顶点作为起始顶点，将其设为当前顶点。<br/>2.访问当前顶点v，输出关于v的信息。<br/>3.将v的访问标志置为已访问。<br/>4.如果v的邻接点中存在未被访问的顶点w，则将w设为当前顶点，重复步骤2-3。<br/>5.如果v的所有邻接点都已被访问过，则回退到最近被访问过的且仍有未被访问邻接点的顶点u，重复步骤4。<br/>6.如果所有顶点均已访问，则遍历结束；否则，选择未被访问的另一个顶点作为起始顶点，重复步骤1-5。"},{"id":"dsa13003-pl-P4604383","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"简述普里姆算法的基本思想。","opts":[],"ans":null,"explain":"普里姆算法从图中任选的初始顶点开始，逐步增加边和顶点，直到构成包含所有顶点的最小生成树。在每一步中，选择连接已选顶点集合U与未选顶点集合V-U之间权值最小的边，并将其加入最小生成树中，同时将该边连接的未选顶点加入U中。重复此过程，直到U包含所有顶点为止。"},{"id":"dsa13003-pl-P4604336","type":"calc","tier":"创新","conf":"adapt","chap":"第5-6章","q":"阅读以下关于最大堆插入操作的伪代码，并简述其关键步骤。 function insert(heap, x): n = heap.length heap[n] = x // 将新元素添加到堆的末尾 n = n + 1 while n &gt; 1 and heap[(n-1)//2] &lt; heap[n-1]: heap[n-1], heap[(n-1)//2] = heap[(n-1)//2], heap[n-1] // 交换元素 n = n - 1","opts":[],"ans":null,"explain":"1.添加新元素：将新元素x添加到堆的末尾，并更新堆的大小n。<br/>2.比较与交换：从新元素开始，与其父节点进行比较。如果新元素大于其父节点，则交换两者的位置。<br/>3.继续调整：重复步骤2，直到新元素小于或等于其父节点，或者新元素已经到达堆顶（即n=1时）。<br/>4.结束：当新元素不再需要调整时，插入操作完成。"},{"id":"dsa13003-pl-P4604337","type":"calc","tier":"创新","conf":"adapt","chap":"第5-6章","q":"请简述对一棵树进行后序遍历的算法步骤，并给出关键点。","opts":[],"ans":null,"explain":"1.判断根节点；<br/>2.遍历子树；<br/>3.访问根节点。<br/>关键点：<br/>1.递归调用；<br/>2.子树先遍历；<br/>3.访问顺序。"},{"id":"dsa13003-pl-P4604338","type":"calc","tier":"创新","conf":"adapt","chap":"第5-6章","q":"请简述如何设计一个满足前缀特性的变长编码方案，并给出关键点。","opts":[],"ans":null,"explain":"1.统计字符频率；<br/>2.构建哈夫曼树；<br/>3.生成编码。<br/>关键点：<br/>1.频率优先；<br/>2.前缀特性；<br/>3.哈夫曼树。"},{"id":"dsa13003-pl-P4604339","type":"calc","tier":"创新","conf":"adapt","chap":"第5-6章","q":"设计一个算法，用于从给定的哈夫曼编码字符串中译码出原文。","opts":[],"ans":null,"explain":"1.初始化：从哈夫曼树的根结点开始。<br/>2.逐位扫描：遍历编码字符串的每一位。<br/>3.选择分支：根据当前位是0还是1，选择向左或向右分支。<br/>4.到达叶结点：如果到达叶结点，则输出该叶结点对应的字符，并回到根结点继续译码。<br/>5.继续扫描：继续扫描编码字符串的下一位，重复步骤3和4。<br/>6.结束：当编码字符串扫描完毕时，译码过程结束。"},{"id":"dsa13003-pl-P4604340","type":"calc","tier":"创新","conf":"adapt","chap":"第5-6章","q":"阅读以下算法描述，并简述其实现的功能。 算法：DFS遍历无向图 输入：无向图G=(V, E)，起始顶点start 输出：从start开始的深度优先遍历序列 1. 初始化一个空栈stack和一个用于记录访问状态的数组visited，所有元素初始化为false 2. 将start入栈，并设置visited[start]为true 3. 当栈不为空时，执行以下步骤： A.从栈中弹出一个顶点v B.访问顶点v（例如，打印v） C.遍历v的所有邻接点u，如果visited[u]为false，则将u入栈并设置visited[u]为true","opts":[],"ans":null,"explain":"1.功能描述：该算法实现了对无向图G的深度优先遍历（DFS），从指定的起始顶点start开始，遍历图中所有可达的顶点，并按照深度优先的顺序输出它们。<br/>2.实现方式：通过维护一个栈来模拟递归过程，利用栈的先入后出特性来确保遍历的深度优先性。同时，使用一个visited数组来记录每个顶点的访问状态，避免重复访问。<br/>3.遍历过程：从起始顶点开始，将其入栈并标记为已访问。然后，不断从栈中弹出顶点，并访问它。对于每个被访问的顶点，遍历其所有未访问的邻接点，将它们入栈并标记为已访问。这个过程一直进行，直到栈为空，即所有可达的顶点都被访问过。"},{"id":"dsa13003-pl-P4604341","type":"calc","tier":"创新","conf":"adapt","chap":"第5-6章","q":"阅读以下关于邻接表创建过程的描述，并回答以下问题。 描述：在创建邻接表时，首先创建一个大小为n的数组，用于存储每个顶点对应的单链表头指针。然后，对于图中的每条边，找到对应的两个顶点vi和vj，在vi对应的单链表中添加一个指向vj的节点（无向图中还需要在vj对应的单链表中添加一个指向vi的节点）。 1.初始步骤：创建邻接表的第一步是什么？ 2.在添加边(vi, vj)到无向图的邻接表时，需要在哪两个链表中添加节点？","opts":[],"ans":null,"explain":"1.创建一个大小为n的数组。                             2.vi对应的链表和vj对应的链表。"},{"id":"dsa13003-pl-P4604342","type":"calc","tier":"创新","conf":"adapt","chap":"第5-6章","q":"VerToNum函数实现的功能是什么？请简要概述。","opts":[],"ans":null,"explain":"1.初始化索引变量i为0。<br/>2.通过循环遍历顶点表verticesList，寻找给定的顶点u。<br/>3.循环条件为顶点u不等于当前遍历到的顶点g.verticesList[i]且下标i小于顶点总数getNumVertices(g)。<br/>4.如果找到顶点u，则返回其在顶点表中的下标i。<br/>5.如果遍历完顶点表仍未找到顶点u，则返回-1表示未找到。"},{"id":"dsa13003-pl-P4604343","type":"calc","tier":"创新","conf":"adapt","chap":"第5-6章","q":"阅读以下关于广度优先搜索（BFS）的算法描述，并回答问题。 算法描述： 1.选择图中指定的顶点v作为起始顶点，将其入队列，并标记为已访问。 2.当队列不为空时，执行以下步骤： A.从队列中取出一个顶点w。 B.访问顶点w。 C.遍历w的所有邻接点，将未访问的邻接点加入队列并标记为已访问。 3.重复步骤2，直到队列为空。 问题： 1.广度优先搜索的遍历顺序特点是什么？ 2.广度优先搜索中，队列的作用是什么？ 3.当用邻接表表示图时，广度优先搜索算法的时间复杂度为何是O(|V|+|E|)？","opts":[],"ans":null,"explain":"1.由近及远，逐层遍历。                                   2.存储待访问的顶点，保证顶点按访问顺序被处理。                                                       3.每个顶点入队列和出队列各一次，每个边被检查一次。"},{"id":"dsa13003-pl-P4604344","type":"calc","tier":"创新","conf":"adapt","chap":"第5-6章","q":"阅读以下克鲁斯卡尔算法的部分代码，回答问题： # 假设已经有一个按权值排序的边数组edge # flag数组用于记录每个顶点所属的连通分量 def Kruskal(n, edge): # 初始化MST为空，flag数组初始化为顶点编号 MST = [] flag = [i for i in range(n)] # 遍历边数组 for e in edge: u, v, weight = e # 判断u和v是否属于不同的连通分量 if find(flag, u) != find(flag, v): # 将边添加到MST中 MST.append(e) # 合并连通分量 union(flag, u, v) # 如果MST已包含n-1条边，则结束 if len(MST) == n - 1: break return MST # 假设find和union函数已经定义，用于并查集操作 1. `find`函数的作用是什么？ 2. `union`函数的作用是什么？ 3. 为什么要在`if len(MST) == n - 1:`处使用`break`？","opts":[],"ans":null,"explain":"1.查找顶点所属的连通分量。                           2.合并两个连通分量。                                         3.当MST包含n-1条边时，已经构成最小生成树，无需继续添加边。"},{"id":"dsa13003-pl-P4604445","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-6章","q":"在最大堆中插入新元素时，新元素首先被放置在堆的__1__位置，然后向上调整。","opts":[],"ans":["末尾（或最后一个空位置）"],"explain":"在最大堆中插入新元素x时，先将x保存在堆中第一个空位置，然后将x向上调整到合适的位置。\n参考答案: A.末尾（或最后一个空位置）"},{"id":"dsa13003-pl-P4604446","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-6章","q":"在优先队列中，元素的“最优先”是由其__1__决定的。","opts":[],"ans":["优先值"],"explain":"输出时，选择最优先的元素输出。‘最优先’取决于优先值的定义。\n参考答案: A.优先值"},{"id":"dsa13003-pl-P4604447","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-6章","q":"在使用孩子-兄弟表示法时，树中的每个结点都包含两个指针域，分别指向该结点的__1__和__2__。","opts":[],"ans":["第一个孩子结点B.下一个兄弟结点"],"explain":"孩子-兄弟表示法为每个结点定义了一个存储结点，包含左、右两个指针域。左指针域指向该结点的第一个孩子结点，右指针域指向该结点的下一个兄弟结点。\n参考答案: A.第一个孩子结点B.下一个兄弟结点"},{"id":"dsa13003-pl-P4604448","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-6章","q":"在将一棵二叉树还原为森林的过程中，若二叉树的根结点没有__1__，则还原后的森林只有一棵树。","opts":[],"ans":["右子树"],"explain":"“规则2：将二叉树还原为森林”中提到，若B非空，则B的根root作为F中第一棵树T₁的根；B的左子树BL还原得到的森林作为T₁的各子树；B的右子树BR还原得到的森林作为F中的T₂, T₃, …, Tm。这意味着，如果二叉树的根结点没有右子树（即BR为空），则还原过程中只会有由根结点和其左子树构成的树，即还原后的森林只有一棵树。\n参考答案: A.右子树"},{"id":"dsa13003-pl-P4604449","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-6章","q":"对于一棵由n个结点组成的树，其先序遍历和后序遍历结果中，每个结点都恰好出现__1__次。","opts":[],"ans":["一"],"explain":"无论是先序遍历还是后序遍历，树中的每个结点都会被访问一次且仅一次，因此每个结点都恰好出现一次。\n参考答案: A.一"},{"id":"dsa13003-pl-P4604450","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-6章","q":"Unicode编码使用__1__位二进制表示一个字符，而ASCII编码使用__2__位二进制表示一个字符。","opts":[],"ans":["16B.8"],"explain":"Unicode编码的字符集不但包含ASCII编码的字符集，而且包含一些自然语言使用的字符，如汉字等，使用16位二进制表示一个字符。\n参考答案: A.16B.8"},{"id":"dsa13003-pl-P4604451","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-6章","q":"哈夫曼树又称为__1__，其WPL（外部带权路径长度）是最小的。","opts":[],"ans":["最优二叉树"],"explain":"哈夫曼树的WPL是最小的，即哈夫曼树是带权路径长度最短的树，因此它又称为最优二叉树。\n参考答案: A.最优二叉树"},{"id":"dsa13003-pl-P4604452","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-6章","q":"哈夫曼编码的带权平均码长是通过__1__除以__2__计算得到的。","opts":[],"ans":["译文总位数B.原文字符总数"],"explain":"编码的带权平均码长=译文总位数/原文字符总数。\n参考答案: A.译文总位数B.原文字符总数"},{"id":"dsa13003-pl-P4604453","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-6章","q":"在图G=(V, E)中，若|V|=n，则该无向图最多可以有__1__条边。","opts":[],"ans":["n(n-1)","2"],"explain":"在有n个顶点的无向图中，其边数最多可达n(n-1)/2。\n参考答案: A.n(n-1)/2"},{"id":"dsa13003-pl-P4604454","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-6章","q":"在图的基本操作中，使用单字符表示顶点，这些顶点保存在顶点表__1__中。","opts":[],"ans":["verticesList[MaxVtxNum]"],"explain":"顶点使用单字符表示，保存在顶点表verticesList[MaxVtxNum]中。\n参考答案: A.verticesList[MaxVtxNum]"},{"id":"dsa13003-pl-P4604455","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-6章","q":"当图G含有n个顶点时，无向图的邻接矩阵最多有__1__个非零元素。","opts":[],"ans":["n(n-1)"],"explain":"无向图的邻接矩阵是对称的，且对角线上的元素都为0（因为图中不含有自环）。因此，对于一个含有n个顶点的无向图，其邻接矩阵中最多可以有n(n-1)/2条边（每条边对应矩阵中的两个非零元素），所以最多有n(n-1)个非零元素。\n参考答案: A.n(n-1)"},{"id":"dsa13003-pl-P4604456","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-6章","q":"在邻接表中，对于有向图，如果要计算顶点vi的入度，需要遍历__1__中的n个单链表。","opts":[],"ans":["邻接表"],"explain":"对于有向图，如果要计算顶点vi的入度，则需要遍历邻接表中所有的n个单链表，找出顶点为vi的结点个数。\n参考答案: A.邻接表"},{"id":"dsa13003-pl-P4604457","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-6章","q":"邻接表的空间复杂度为__1__。","opts":[],"ans":["O(n+e)"],"explain":"邻接表的空间复杂度为O(n+e)。当图中边的数目远远小于顶点的数目时，邻接表所需的存储空间要比邻接矩阵的少。\n参考答案: A.O(n+e)"},{"id":"dsa13003-pl-P4604458","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-6章","q":"NumToVer函数用于返回顶点表verticesList中下标i对应的顶点。如果下标i在有效范围内，则函数返回__1__。","opts":[],"ans":["g.verticesList[i]"],"explain":"根据图片中的NumToVer函数实现，如果下标i在有效范围内（即大于等于0且小于顶点总数getNumVertices(g)），则函数返回顶点表verticesList中下标i对应的顶点，即g.verticesList[i]。\n参考答案: A.g.verticesList[i]"},{"id":"dsa13003-pl-P4604459","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-6章","q":"深度优先搜索（DFS）的时间复杂度在邻接表作为存储结构时，为__1__。","opts":[],"ans":["O(|V|+|E|)"],"explain":"当将邻接表作为存储结构时，邻接表各单链表中的所有结点共有2×|E|个，这里，|E|是图中的边数。这样，遍历边的时间复杂度为O(|E|)。遍历每个顶点的次数最多为1，深度优先搜索的时间复杂度为O(|V|+|E|)。\n参考答案: A.O(|V|+|E|)"},{"id":"dsa13003-pl-P4604460","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-6章","q":"广度优先搜索（BFS）从图中任意指定的起始顶点v开始，访问顶点v后，然后访问与v相邻接的所有尚未被访问过的顶点，这个过程会__1__。","opts":[],"ans":["依次进行"],"explain":"然后访问与v相邻接的所有尚未被访问过的顶点。\n参考答案: A.依次进行"},{"id":"dsa13003-pl-P4604461","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-6章","q":"广度优先搜索算法的时间复杂度，当用邻接表表示图时，为__1__。","opts":[],"ans":["O(|V|+|E|)"],"explain":"当用邻接表表示图时，广度优先搜索算法的时间复杂度为O(|V|+|E|)。\n参考答案: A.O(|V|+|E|)"},{"id":"dsa13003-pl-P4604462","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-6章","q":"深度优先搜索时得到的生成树称为__1__。","opts":[],"ans":["深度优先生成树"],"explain":"进行深度优先搜索时得到的生成树称为深度优先生成树。\n参考答案: A.深度优先生成树"},{"id":"dsa13003-pl-P4604463","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-6章","q":"最小生成树（MST）是图中所有顶点及其边子集的图，其边的权值之和是__1__。","opts":[],"ans":["最小的"],"explain":"权值之和最小的那棵生成树具有特殊意义。将边的权值之和最小的生成树称为最小代价生成树（MST），简称为最小生成树。\n参考答案: A.最小的"},{"id":"dsa13003-pl-P4604464","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-6章","q":"克鲁斯卡尔算法在每次选择边时，需要判断该边的两个顶点是否属于__1__的连通分量。","opts":[],"ans":["不同"],"explain":"如果这条边所依附的两个顶点分别在生成树的两个连通分量上，则将这条边添加到生成树中。\n参考答案: A.不同"},{"id":"dsa13003-pl-P4604226","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"在C语言中，二维数组int arr[3][4] = {{1, 2}, {3}, {4, 5, 6, 7}};中，arr[2][1]的值是（）。","opts":["A. 0","B. 1","C. 3","D. 5"],"ans":3,"explain":"二维数组的定义，arr[2][1]代表的是第三行（因为数组下标从0开始）、第二列的元素。在给定的初始化列表中，第三行被明确赋值为{4, 5, 6, 7}，因此arr[2][1]的值是5。"},{"id":"dsa13003-pl-P4604227","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"在C语言中，定义一个二维数组int arr[5][4];，若采用行主序方式存储，且每个整数元素占4个字节，若arr[0][0]的存储地址是1000，则arr[3][2]的存储地址是（）。","opts":["A. 1064","B. 1068","C. 1056","D. 1076"],"ans":2,"explain":"1. 明确核心公式行主序下，二维数组元素地址计算公式为：LOC(i,j)=LOC(0,0)+(i×每行元素个数+j)×单个元素字节数2. 提取题目参数数组定义：int arr[5][4] → 行数 5，列数 4（即每行有 4 个元素）单个元素大小：4 字节首地址 LOC(0,0)：1000目标元素 arr[3][2]：行号 i=3，列号 j=23. 代入计算LOC(3,2)​=1000+(3×4+2)×4=1000+(12+2)×4=1000+14×4=1000+56=1056​4. 原理说明从 arr[0][0] 到 arr[3][2]，需要先存满前 3 行（共 3×4=12 个元素），再存第 3 行的前 2 个元素（arr[3][0] 和 arr[3][1]），总共跨越 14 个元素。每个元素占 4 字节，总偏移量为 14×4=56 字节，因此地址为 1000+56=1056。"},{"id":"dsa13003-pl-P4604228","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"对于一个n×n的对称矩阵，如果采用压缩存储方式仅保存其下三角部分（包括对角线），则最多需要保存的元素个数是（）。","opts":["A. n^2","B. n^2/2","C. n(n+1)/2","D. n(n-1)/2"],"ans":2,"explain":"对于n×n的对称矩阵，其下三角部分（包括对角线）共有n×(n+1)/2个元素。这是因为对角线有n个元素，而下三角部分（不包括对角线）的每一行比上一行多一个元素，形成等差数列，求和得到n(n-1)/2，加上对角线的n个元素，即n×(n+1)/2。"},{"id":"dsa13003-pl-P4604229","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"在“老鼠走迷宫”问题中，若当前位置为[i][j]，且想要向右走，则新位置的行号和列号应（）。","opts":["A. 行号不变，列号加1","B. 行号加1，列号不变","C. 行号减1，列号加1","D. 行号减1，列号不变"],"ans":0,"explain":"若向右走，则行值不变，列值加1。"},{"id":"dsa13003-pl-P4604230","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"在广义表L=((a，b)，(c，d，(e，f)))中，求head(tail(head(L)))的结果是（）。","opts":["A. (a，b)","B. (c，d，(e，f))","C. b","D. (e，f)"],"ans":2,"explain":"1.head(L) 提取L的第一个元素，即 (a，b)。 2.tail(head(L)) 提取 (a，b) 的表尾，即 b（因为表头a后的所有元素构成表尾，这里只有一个元素b）。 3.head(tail(head(L))) 最终得到b。"},{"id":"dsa13003-pl-P4604231","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"在C语言中，字符串 &quot;Hello&quot; 实际上占用的内存空间大小是（ ）。","opts":["A. 4字节","B. 5字节","C. 6字节","D. 依赖编译器实现"],"ans":2,"explain":"C语言中没有字符串类型，而是提供了字符数组，将字符串作为字符数组来处理。当使用字符数组表示一个字符串时，C语言规定使用一个字符串结束标志 &#039;\\0&#039; 表示串的结尾。"},{"id":"dsa13003-pl-P4604232","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"以下关于字符串的说法，（）是错误的。","opts":["A. 空串和空白串是同一个概念。","B. 字符串 &quot;abc&quot; 的长度是 3。","C. 字符串 &quot;C++&quot; 在内存中占用的空间大小至少为 4 字节（不包括可能的额外空间用于对齐）。","D. 字符串 &quot;Hello\\0World&quot; 在C语言中是不合法的，因为它包含了额外的 &#039;\\0&#039;。"],"ans":0,"explain":"注意 &quot; &quot; 和 &quot;&quot; 分别表示长度为1的空白串与长度为0的空串，这两者是不一样的。"},{"id":"dsa13003-pl-P4604233","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"在KMP算法中，当模式串P在主串T中某位置失配时，模式串P应该右移的位数由（）向量决定。","opts":["A. prev","B. next","C. fail","D. skip"],"ans":1,"explain":"在KMP算法中，当模式串P在主串T中某位置失配时，模式串P应该右移的位数由特征向量next决定。next数组存储了模式串P中每个位置失配时，模式串应该向前移动多少位以继续匹配。"},{"id":"dsa13003-pl-P4604234","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"在一棵树中，除根结点外，每个结点有且仅有一个（）。","opts":["A. 后继结点","B. 前驱结点","C. 兄弟结点","D. 父结点"],"ans":1,"explain":"除根结点以外，每个结点均只有一个前驱结点。"},{"id":"dsa13003-pl-P4604235","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"下列（）描述符合树的基本定义。","opts":["A. 树是由无限个结点组成的集合","B. 树中所有结点的度必须相同","C. 树中只有一个根结点","D. 树中的边可以形成环路"],"ans":2,"explain":"一棵树（tree）T是由一个或一个以上的结点组成的有限集，其中有一个特定的结点R称为树T的根结点。"},{"id":"dsa13003-pl-P4604236","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"一棵高度为5的满二叉树共有（）个结点。","opts":["A. 15","B. 31","C. 32","D. 63"],"ans":1,"explain":"高度为h的二叉树最多有2h-1个结点。"},{"id":"dsa13003-pl-P4604237","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"一棵完全二叉树有10个结点，其高度h至少为（）。","opts":["A. 3","B. 4","C. 5","D. 6"],"ans":1,"explain":"[图]https://file.mshiedu.com/exam/2025-10-14/mnvvsgXFspId6S1H6joKfBOmjMikTFX2d54qt5LA3Mt5gfVtqw.png"},{"id":"dsa13003-pl-P4604238","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"一棵具有n个结点的二叉树，在二叉链表中空指针域的个数是（）。","opts":["A. n - 1","B. n","C. n + 1","D. 2n - 1"],"ans":2,"explain":"设二叉树中有n个结点，每个结点都含有两个指针域，则二叉链表内共有2×n个指针域。已知含有n个结点的树中仅含有n-1个分支，即只有n-1个指针域不为空，则其余的n+1个指针域均为空。"},{"id":"dsa13003-pl-P4604239","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"关于二叉树的顺序存储，以下说法正确的是（）。","opts":["A. 顺序存储的二叉树一定是完全二叉树","B. 顺序存储的二叉树空间利用率高","C. 顺序存储的二叉树方便进行结点间的层次关系查询","D. 顺序存储的二叉树中，任意结点的左右子结点位置可以通过公式直接计算"],"ans":3,"explain":"虽然顺序存储方式的存储效率不高，但原二叉树中各结点的父结点和子结点的存储位置可以通过下标计算出来，访问效率很高。"},{"id":"dsa13003-pl-P4604240","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"在将顺序存储的二叉树转换为二叉链表的过程中，如果某个结点的下标为i，那么其左子结点的下标应为（）。","opts":["A. 2i + 1","B. 2i + 2","C. 2i - 1","D. i * 2"],"ans":0,"explain":"如果下标i处的结点有左子结点，则其应该保存在下标2×i+1处。"},{"id":"dsa13003-pl-P4604241","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"在二叉树的遍历中，如果希望每个结点的编号大于其左右子结点的编号（若存在），并且左子结点的编号小于右子结点的编号（若存在），应该使用（）方法。","opts":["A. 先序遍历","B. 中序遍历","C. 后序遍历","D. 层序遍历"],"ans":2,"explain":"要求每个结点的编号大于其左右子结点的编号，并且左子结点的编号小于右子结点的编号。这与后序遍历的特性一致，即先遍历左子树，再遍历右子树，最后访问根结点。"},{"id":"dsa13003-pl-P4604242","type":"sc","tier":"基础","conf":"adapt","chap":"第5-6章","q":"已知算术表达式的中缀形式为 A+B*C-D/E，其后缀形式为 ABC*+DE/-，该表达式的表达式树进行先序遍历后得到的前缀形式为（ ）。","opts":["A. -A+B*C/DE","B. -A+B*CD/E","C. -+*ABC/DE","D. -+A*BC/DE"],"ans":3,"explain":"中缀形式和后缀形式还原表达式树，然后对表达式树进行先序遍历。先序遍历的顺序是先访问根节点，然后递归地先序遍历左子树，最后递归地先序遍历右子树。根据这个规则，对应的遍历结果是 -+A*BC/DE。"},{"id":"dsa13003-pl-P4604373","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"请简述在C语言中，如何定义一个包含7个元素的整型一维数组，并初始化这些元素为一周每天的名称对应的数值（假设用0-6分别代表星期日到星期六）。","opts":[],"ans":null,"explain":"1.定义数组：在C语言中，定义一个包含7个元素的整型一维数组可以使用以下语句：int daysOfWeek[7];<br/>2.初始化数组：由于C语言在定义数组时直接初始化只能使用具体的值，而不能直接使用字符串（如星期几的名称）作为下标或值。因此，我们可以直接使用数值0到6来初始化这个数组，这些数值代表一周中的每一天。例如：int daysOfWeek[7] = {0, 1, 2, 3, 4, 5, 6};"},{"id":"dsa13003-pl-P4604374","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"请简述KMP算法中next数组的作用，并给出计算next数组的一个简单步骤。","opts":[],"ans":null,"explain":"1.next数组的作用：<br/>next数组在KMP算法中用于存储模式串P中每个位置失配时，模式串应该向前移动多少位以继续匹配。它避免了在失配时模式串整体向右移动一位的低效做法，提高了匹配效率。<br/><br/>2.计算next数组的一个简单步骤：<br/>1）初始化next[0] = -1，next[1] = 0。<br/>2）对于j = 2到m-1（m为模式串P的长度），执行以下步骤：<br/>初始化k = next[j-1]。<br/>当k != -1且P[j] != P[k+1]时，更新k = next[k]。<br/>如果P[j] == P[k+1]，则next[j] = k + 1；否则，next[j] = 0。"},{"id":"dsa13003-pl-P4604375","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"一棵有n个结点的二叉树中，若n₁表示度为1的结点个数，则n₂（度为2的结点个数）至少为n₁/2。","opts":[],"ans":null,"explain":"1.设变量：设二叉树中度为0的结点个数为n₀，度为1的结点个数为n₁，度为2的结点个数为n₂，总结点数为n。<br/>2.建立方程：根据二叉树的性质，有n = n₀ + n₁ + n₂。<br/>3.分析边数：二叉树中的边数（即连接结点的线）总数为n-1（因为根结点没有父结点）。每个度为2的结点贡献2条边，每个度为1的结点贡献1条边，度为0的结点不贡献边。因此，边数也可以表示为2n₂ + n₁。<br/>4.建立不等式：由上述分析可得，2n₂ + n₁ = n - 1。整理得n₂ = (n - 1 - n₁) / 2。<br/>5.推导结论：由于n、n₁均为非负整数，且n &gt; n₁（因为至少有一个根结点），所以(n - 1 - n₁) / 2 ≥ 0，即n₂ ≥ 0。又因为n₁为奇数时，(n - 1 - n₁) / 2不是整数，但n₂必须是整数，所以实际上n₂ ≥ (n - 1 - n₁ + 1) / 2 = n₁ / 2（向上取整）。但在此题中，我们只需证明n₂至少为n₁/2（不考虑取整），因此结论成立。"},{"id":"dsa13003-pl-P4604376","type":"sa","tier":"创新","conf":"adapt","chap":"第5-6章","q":"简述二叉树先序遍历的递归和非递归实现的主要区别。","opts":[],"ans":null,"explain":"1.递归实现：<br/>递归实现简单直观，通过函数调用栈隐式地保存了遍历过程中的状态。<br/>每进入一个递归调用，就访问当前结点，并递归地遍历其左子树和右子树。<br/>当递归调用返回时，表示子树已经遍历完成。<br/>2.非递归实现：<br/>非递归实现需要显式地使用栈来保存遍历过程中的状态。<br/>通常从根结点开始，先将根结点入栈，然后循环处理栈顶元素。<br/>当访问栈顶元素时，首先访问该元素（即当前结点），然后将其右子结点（如果存在）入栈，再将左子结点（如果存在）入栈。<br/>这样做的目的是保证先遍历左子树，再遍历右子树。"},{"id":"dsa13003-pl-P4604330","type":"calc","tier":"创新","conf":"adapt","chap":"第3-4章","q":"阅读以下C语言代码片段，解释并计算B[2][3]的存储地址，假设A[0][0]的存储地址是1000，每个整数占4个字节。 int A[4][5]; // 假设A数组已按行主序存储 int (*B)[5] = A + 2; // B是一个指向含有5个整数的数组的指针，指向A的第3行","opts":[],"ans":null,"explain":"1.理解代码：B是一个指针，指向一个包含5个整数的数组，即指向A数组的第3行（因为数组下标从0开始，所以A+2指向第3行）。<br/>2.计算偏移：由于A[0][0]的存储地址是1000，且每个整数占4个字节，A数组的第3行（即A[2]或B指向的行）的起始地址是1000 + 2 * 5 * 4 = 1040（因为每行有5个整数，共20字节，前两行共占40字节）。<br/>3.定位元素：在B指向的数组中，B[2][3]实际上是不存在的（因为B指向的数组只有5个元素，索引范围是0到4），但如果问题意图是询问A[2][3]（即B[0][3]，因为B已经指向了A的第3行）的存储地址，则它是1040 + 3 * 4 = 1052（从第3行的起始地址开始，偏移3个整数的位置）。但根据题目直接问B[2][3]，这实际上是一个越界访问，不过如果理解为在A数组中的位置，那么应该是A[4][3]（但注意A只有4行，这也是越界的），这里我们按A[2][3]解释。"},{"id":"dsa13003-pl-P4604331","type":"calc","tier":"创新","conf":"adapt","chap":"第3-4章","q":"设计一个算法，用于将稀疏矩阵A（使用三元组表表示）转置为稀疏矩阵B，并返回B的三元组表。","opts":[],"ans":null,"explain":"1.初始化：创建两个数组ColSize和RowNext，分别用于记录转置后矩阵B的每列非零元素个数和每行当前非零元素的起始位置。<br/>2.计算ColSize：遍历A的三元组表，统计每个列号j出现的次数，存储在ColSize[j]中。<br/>3.计算RowNext：根据ColSize数组，计算RowNext数组。RowNext[0] = 0，对于k &gt; 0，RowNext[k] = RowNext[k-1] + ColSize[k-1]。<br/>4.转置：遍历A的三元组表，对于每个三元组(i, j, v)，根据RowNext[j]找到在B中的位置，将(j, i, v)插入到B的三元组表中，并更新RowNext[j] += 1。<br/>5.返回结果：返回B的三元组表。"},{"id":"dsa13003-pl-P4604332","type":"calc","tier":"创新","conf":"adapt","chap":"第3-4章","q":"请简述“老鼠走迷宫”算法中回溯的步骤，并指出该步骤的主要作用。","opts":[],"ans":null,"explain":"1.回溯步骤：<br/>当当前位置无法继续前行时（即所有可探查的方向均受阻），从栈中弹出一个元素（即退回到前一个位置）。<br/>更改当前位置为栈顶元素所表示的位置，并尝试之前未探查的方向。<br/>2.主要作用：<br/>避免程序陷入死循环，确保当某条路径无法到达终点时，能够返回并尝试其他可能的路径。<br/>通过栈来记录路径信息，确保在回溯过程中能够准确返回到之前的位置，并继续寻找可行的路径。"},{"id":"dsa13003-pl-P4604333","type":"calc","tier":"创新","conf":"adapt","chap":"第3-4章","q":"阅读以下关于KMP算法的描述，并回答问题： 在KMP算法中，若模式串P=&quot;abcabc&quot;，主串T=&quot;abcabcabc&quot;，则模式串P首次在主串T中匹配成功的位置是什么。","opts":[],"ans":null,"explain":"初始时，模式串P的首字符与主串T的首字符对齐。 依次比较P和T的对应字符，直到P的所有字符都与T的对应字符匹配。 在这个例子中，模式串P=&quot;abcabc&quot;与主串T=&quot;abcabcabc&quot;从位置0开始完全匹配，因此模式串P首次在主串T中匹配成功的位置是0。\n0"},{"id":"dsa13003-pl-P4604334","type":"calc","tier":"创新","conf":"adapt","chap":"第5-6章","q":"阅读以下代码段，简述其功能。 typedef struct BinTNode { ElemType data; struct BinTNode *lchild; struct BinTNode *rchild; } BinTNode, *BinTree; void CreateBinaryTree(BinTree *T) { // 假设这里是通过某种方式创建二叉树的代码 // ... } void CountEmptyPointers(BinTree T, int *emptyCount) { if (T == NULL) return; if (T-&gt;lchild == NULL) (*emptyCount)++; if (T-&gt;rchild == NULL) (*emptyCount)++; CountEmptyPointers(T-&gt;lchild, emptyCount); CountEmptyPointers(T-&gt;rchild, emptyCount); } int main() { BinTree T = NULL; CreateBinaryTree(&amp;T); // 假设成功创建了一个二叉树 int emptyCount = 0; CountEmptyPointers(T, &amp;emptyCount); printf(&quot;The number of empty pointers is: %d\\n&quot;, emptyCount); return 0; }","opts":[],"ans":null,"explain":"1.定义二叉树节点结构体。<br/>2.创建二叉树（具体创建过程未给出）。<br/>3.递归计算并统计二叉树中所有空指针的数量。<br/>4.输出空指针的总数。"},{"id":"dsa13003-pl-P4604335","type":"calc","tier":"创新","conf":"adapt","chap":"第5-6章","q":"阅读以下非递归实现二叉树先序遍历的伪代码，简述其工作流程。 void PreorderTraversal(BinTree T) { if (T == NULL) return; Stack S; InitStack(&amp;S); Push(&amp;S, T); while (!IsEmpty(S)) { T = Pop(&amp;S); Visit(T); // 假设Visit函数用于访问结点 if (T-&gt;rchild != NULL) Push(&amp;S, T-&gt;rchild); if (T-&gt;lchild != NULL) Push(&amp;S, T-&gt;lchild); } }","opts":[],"ans":null,"explain":"1.初始化：首先检查二叉树T是否为空，如果为空则直接返回。然后初始化栈S。<br/>2.根结点入栈：将根结点T入栈。<br/>3.循环遍历：进入循环，只要栈不为空，就持续遍历。<br/>4.访问栈顶元素：从栈中弹出栈顶元素（即当前结点），并访问该结点。<br/>5.右子结点入栈：如果当前结点的右子结点存在，则将其入栈。注意，这里与常规顺序（先左后右）相反，是因为栈是后进先出的数据结构，这样处理可以确保左子树先被遍历。<br/>6.左子结点入栈：如果当前结点的左子结点存在，则将其入栈。<br/>7.重复步骤3-6：直到栈为空，即所有结点都被访问过。"},{"id":"dsa13003-pl-P4604431","type":"fill","tier":"拔高","conf":"adapt","chap":"第3-4章","q":"在C语言中，如果定义了一个二维数组int weekTemps[7][1] = {{30}, {28}, {29}, {32}, {28}, {30}, {31}};，则weekTemps[4][0]的值是__1__。","opts":[],"ans":["28"],"explain":"weekTemps是一个7行1列的二维数组，每个元素都是一个整数。weekTemps[4][0]代表的是第五行（下标为4）第一列（下标为0）的元素，其值为28。\n参考答案: A.28"},{"id":"dsa13003-pl-P4604432","type":"fill","tier":"拔高","conf":"adapt","chap":"第3-4章","q":"在C语言中，定义一个三维整型数组int cube[2][3][4];，采用行主序方式存储，若每个整数占4个字节，且cube[0][0][0]的存储地址为1000，则cube[1][2][3]的存储地址是__1__。","opts":[],"ans":null,"explain":"[图]https://file.mshiedu.com/exam/2025-10-15/755hgPskbC2ngJ1VNawy3wHEUdxhO1in5XHJlICuXeq3JtSbuj.png"},{"id":"dsa13003-pl-P4604433","type":"fill","tier":"拔高","conf":"adapt","chap":"第3-4章","q":"在稀疏矩阵的存储中，每个非零元素被存储为一个三元组(i, j, v)，其中v表示非零元素的值，i和j分别表示该元素所在的__1__和__2__。","opts":[],"ans":["行号B.列号"],"explain":"稀疏矩阵中的非零元素被存储为三元组(i, j, v)，其中i表示元素所在的行号，j表示元素所在的列号，v表示该非零元素的值。\n参考答案: A.行号B.列号"},{"id":"dsa13003-pl-P4604434","type":"fill","tier":"拔高","conf":"adapt","chap":"第3-4章","q":"在“老鼠走迷宫”的算法实现中，为了避免重复并找出确定的可行路径，需要一个栈来记录已走过的每一步的位置及方向，栈中的元素是一个含三个分量的结构，其中i用于存储__1__，j用于存储__2__，d用于表示方向。","opts":[],"ans":["行值（或行号）B.列值（或列号）"],"explain":"栈元素为一个含三个分量的结构，i存储行值，j存储列值，d表示方向。\n参考答案: A.行值（或行号）B.列值（或列号）"},{"id":"dsa13003-pl-P4604435","type":"fill","tier":"拔高","conf":"adapt","chap":"第3-4章","q":"广义表A=((x，y)，z，((a，b)，c))的表尾是__1__，深度是__2__。","opts":[],"ans":["表尾是 (z","((a","b)","c))B.深度是 3。"],"explain":"1.表尾是除了表头以外的所有元素组成的表，即 (z，((a，b)，c))。 2.深度计算：最外层表A的深度为1，子表((x，y))的深度为2（因为里面还有一个子表），子表((a，b)，c)的深度也是2（包含两个原子和一个子表，但子表深度为1），所以A的深度为max{2，2}+1=3。\n参考答案: A.表尾是 (z，((a，b)，c))B.深度是 3。"},{"id":"dsa13003-pl-P4604436","type":"fill","tier":"拔高","conf":"adapt","chap":"第3-4章","q":"在C语言中，字符串 &quot;Hello, World!&quot; 的长度为__1__，但它在内存中占用的空间大小至少为__2__字节（包括结束符 &#039;\\0&#039;）。","opts":[],"ans":["13B.14"],"explain":"字符串 &quot;Hello, World!&quot; 包含12个字符和1个结束符 &#039;\\0&#039;，因此总长度为13。但在内存中，由于需要存储结束符 &#039;\\0&#039;，所以占用的空间大小至少为14字节。\n参考答案: A.13B.14"},{"id":"dsa13003-pl-P4604437","type":"fill","tier":"拔高","conf":"adapt","chap":"第3-4章","q":"KMP算法通过构建模式串P的__1__数组来减少不必要的比较，从而提高匹配效率。","opts":[],"ans":["next"],"explain":"KMP算法通过构建模式串P的next数组来记录每个位置失配时，模式串应该向前移动多少位以继续匹配，从而避免了不必要的比较，提高了匹配效率。\n参考答案: A.next"},{"id":"dsa13003-pl-P4604438","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-6章","q":"在树中，如果某个结点位于第i层（i≥0），则它的子结点位于第__1__层。","opts":[],"ans":["i+1"],"explain":"设根为0层，根的子结点为1层，依此类推。一般地，若某个结点位于i（i≥0）层，则它的子结点位于i+1层。\n参考答案: A.i+1"},{"id":"dsa13003-pl-P4604439","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-6章","q":"度为0的结点称为__1__结点或终端结点。","opts":[],"ans":["叶"],"explain":"度为0的结点称为叶结点，或终端结点。\n参考答案: A.叶"},{"id":"dsa13003-pl-P4604440","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-6章","q":"一棵二叉树中，若叶结点个数为n₀，度为2的结点个数为n₂，则度为1的结点个数为__1__。","opts":[],"ans":["n - n₀ - n₂"],"explain":"设二叉树T中度为1的结点的个数为n₁，则T中结点总数n为n=n₀+n₁+n₂。\n参考答案: A.n - n₀ - n₂"},{"id":"dsa13003-pl-P4604441","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-6章","q":"一棵具有n个结点的二叉树，其二叉链表中共有__1__个空指针域。","opts":[],"ans":["n+1"],"explain":"设二叉树中有n个结点，每个结点都含有两个指针域，则二叉链表内共有2×n个指针域。已知含有n个结点的树中仅含有n-1个分支，即只有n-1个指针域不为空，则其余的n+1个指针域均为空。\n参考答案: A.n+1"},{"id":"dsa13003-pl-P4604442","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-6章","q":"在二叉树的顺序存储转换为二叉链表的过程中，为了区分空白元素和正常结点，可以使用一个特殊的值NA。如果结点中保存的是整型值，则NA通常取整型中的__1__。","opts":[],"ans":["最小值"],"explain":"了将它们与保存正常值的结点区分开，需要在这些位置保存一个特殊的值：NA。比如，若二叉树的结点中保存的是整型值，则NA可以取整型中的最小值。\n参考答案: A.最小值"},{"id":"dsa13003-pl-P4604443","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-6章","q":"在二叉树的非递归遍历中，为了保存尚未遍历的信息，通常会使用__1__数据结构。","opts":[],"ans":["栈"],"explain":"在二叉树的非递归遍历中，由于不能同时遍历左右子树，需要借助栈来保存尚未遍历的信息，以便在遍历完左子树后能够继续遍历右子树。\n参考答案: A.栈"},{"id":"dsa13003-pl-P4604444","type":"fill","tier":"拔高","conf":"adapt","chap":"第5-6章","q":"表达式 A+B*C-D/E 的后缀形式为 ABC*+DE/-，其表达式树进行__1__遍历后，可以得到中缀形式 A+B*C-D/E（不含括号）。","opts":[],"ans":["中序"],"explain":"中序遍历的顺序是先递归地中序遍历左子树，然后访问根节点，最后递归地中序遍历右子树。对于表达式树来说，这样的遍历顺序会得到不带括号的中缀表达式。\n参考答案: A.中序"},{"id":"dsa13003-pl-P4604205","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在下列（）情况下，使用顺序表作为线性表的实现方式会更加合适。","opts":["A. 线性表的元素个数频繁变化，且变化范围较大。","B. 线性表需要频繁进行随机访问操作。","C. 线性表的数据元素大小远大于指针大小。","D. 线性表需要在不同位置频繁进行插入和删除操作。"],"ans":1,"explain":"当需要频繁进行随机访问操作时，顺序表更加合适。因为顺序表支持通过索引直接访问元素，时间复杂度为O(1)，而链表则需要从头节点开始逐个遍历，时间复杂度为O(n)。"},{"id":"dsa13003-pl-P4604206","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在链表操作中，为了减少频繁调用malloc和free函数带来的时间开销，可以引入（）数据结构来管理暂时不用的结点。","opts":["A. 栈","B. 队列","C. 空闲单元链表","D. 双向链表"],"ans":2,"explain":"空闲单元链表（Freelist）是一种用于管理暂时不用的链表结点的数据结构。当从链表中删除一个结点时，该结点可以被插入到空闲单元链表中，以便后续重用。这样可以减少调用malloc和free的次数，从而提高程序的效率。"},{"id":"dsa13003-pl-P4604207","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"静态链表是使用哪种数据结构来实现链表的功能的（）。","opts":["A. 栈","B. 队列","C. 一维数组","D. 二叉树"],"ans":2,"explain":"静态链表是使用一维数组来实现的链表，每个数组元素包含数据域和指针域（通常使用数组索引来表示），以模拟链表的行为。"},{"id":"dsa13003-pl-P4604208","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在查找单链表倒数第k个结点的过程中，如果front指针在移动k步后到达了链表末尾，那么说明（）。","opts":["A. 链表长度小于k","B. 链表长度等于k","C. 链表长度大于k","D. 无法确定链表长度与k的关系"],"ans":0,"explain":"使用两个指针front和rear查找单链表倒数第k个结点时，front指针先前进k步作为“排头兵”。如果front在移动k步后到达了链表末尾，这意味着链表中的结点数量不足以支持front前进k步而不超出链表范围，即链表长度小于k。"},{"id":"dsa13003-pl-P4604209","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在查找单链表中间结点的算法中，如果一个指针每次走两步，另一个指针每次走一步，当“排头兵”指针到达链表末尾时，另一个指针指向的是链表的（）位置。","opts":["A. 第一个结点","B. 最后一个结点","C. 中间结点（或当结点数为偶数时，前一个中间结点）","D. 无法确定"],"ans":2,"explain":"为了查找单链表的中间结点（或当结点数为偶数时，前一个中间结点），使用两个指针front和rear从表头开始同步地向表尾方向移动。其中，front指针每次走两步，rear指针每次走一步。当front指针到达链表末尾时，rear指针正好指向链表的中间结点（或当结点数为偶数时，前一个中间结点）。"},{"id":"dsa13003-pl-P4604210","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在单链表逆置的算法中，如果使用了三个指针left、middle和right，其中left和middle分别指向相邻的两个结点，那么在逆置过程中，right指针的作用是（）。","opts":["A. 用来记录middle的下一个结点，确保链表链接不中断","B. 用来指向链表的头结点，保持链表头部不变","C. 用来指向链表的末尾，确保逆置完成后链表完整","D. 没有实际作用，只是算法设计上的冗余"],"ans":0,"explain":"在单链表逆置的算法中，使用三个指针left、middle和right是为了确保在逆置过程中链表的链接不中断。其中，left和middle分别指向相邻的两个结点，而right则用来记录middle的下一个结点。这样，在改变middle的next指针指向left之前，可以通过right指针先保存middle的下一个结点，以确保链表在逆置过程中不会断开。"},{"id":"dsa13003-pl-P4604211","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"以下C语言代码段中，关于链表初始化和创建过程的描述，（）选项是正确的。","opts":["A. 代码段正确初始化了链表，并成功调用了createMyList函数来创建链表。","B. initList函数被错误地用于初始化链表头指针head，并且createMyList函数被调用以初始化链表。","C. 变量i被错误地用于scanf函数接收用户输入，应该使用另一个变量。","D. initList函数被调用但未在代码中定义，因此链表初始化失败。"],"ans":0,"explain":"首先定义了一个头指针LinkList head = NULL;用于链表，这表示链表在初始化时是空的。 接着，虽然代码片段中出现了i=initList（&amp;head）;，但这里initList函数的具体实现并未给出。然而，从上下文推断，initList很可能是用于初始化链表头指针head的函数，将其设置为某种状态（尽管通常链表初始化可能不需要返回值，但这里假设initList返回0表示成功，非0表示失败）。 接下来，通过if语句检查initList的返回值，如果为0（表示成功），则打印“初始化完成”。这表明链表初始化过程被正确处理。 然后，调用createMyList(&amp;head);函数来进一步创建链表（假设该函数根据某些逻辑向链表中添加节点）。 最后，代码准备接收用户输入的值，尽管这里使用了scanf(&quot;%d&quot;, &amp;i);，且i之前用于其他目的，但这并不直接影响链表初始化和创建的正确性，只是表明变量i被重新用于另一个目的。"},{"id":"dsa13003-pl-P4604212","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"设一个栈的入栈序列为1, 2, 3, 4, 5，下列（）序列不可能是其出栈序列。","opts":["A. 1, 2, 3, 4, 5","B. 5, 4, 3, 2, 1","C. 3, 2, 5, 4, 1","D. 2, 1, 4, 3, 5"],"ans":2,"explain":"栈的序列的后进先出。"},{"id":"dsa13003-pl-P4604213","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"在顺序栈的实现中，如果栈顶指针top定义为指向栈顶元素的下一个位置，则下列（）操作序列能正确实现元素x的入栈操作。","opts":["A. top = top + 1; V[top] = x;","B. V[top] = x; top = top - 1;","C. V[top + 1] = x; top = top + 1;","D. top = top - 1; V[top] = x;"],"ans":0,"explain":"栈顶指针top定义为指向栈顶元素的下一个位置。因此，在入栈时，首先需要将top增加1以指向新的栈顶位置，然后将元素x放入该位置。"},{"id":"dsa13003-pl-P4604214","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"在程序设计中，处理函数调用（包括递归调用）时，系统通常使用（）数据结构来保存调用过程中的相关信息，以便在函数返回时能正确恢复执行。","opts":["A. 队列","B. 栈","C. 链表","D. 哈希表"],"ans":1,"explain":"为了能让函数A接续执行，转去函数B之前的相关信息都要保存起来，其目的是从函数B返回后，这些信息逐一恢复，从而函数A能继续执行。保存这些信息的最佳结构是栈。"},{"id":"dsa13003-pl-P4604215","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"在队列这种数据结构中，元素被添加的一端称为（）。","opts":["A. 队头","B. 队尾","C. 栈顶","D. 栈底"],"ans":1,"explain":"定义3-2 队列是只能在表的一端插入、在另一端删除的线性表。能进行插入的一端称为队列尾，简称队尾；能进行删除的一端称为队列头，简称队头。"},{"id":"dsa13003-pl-P4604216","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"队列的主要特性是（）。","opts":["A. 后进先出","B. 先进先出","C. 先进后出","D. 随机访问"],"ans":1,"explain":"这种先来先服务的特性称为先进先出，说明队列的主要特性是先进先出。"},{"id":"dsa13003-pl-P4604217","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"在循环队列中，若rear和front的值相等，则队列的状态是（）。","opts":["A. 队列一定为空","B. 队列一定为满","C. 队列可能为空，也可能为满","D. 队列状态无法确定"],"ans":2,"explain":"条件rear==front也代表空队列。另外，假设队列中只含有一个元素，... 也满足rear==front也成立。条件rear==front也代表空队列。"},{"id":"dsa13003-pl-P4604218","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"链式队列中，入队操作需要修改（）。","opts":["A. 仅队头指针","B. 仅队尾指针","C. 队头指针和队尾指针都要修改","D. 队头指针和队尾指针都不需要修改"],"ans":1,"explain":"入队时，新元素插入在队尾，队尾指针一定要修改，让它指向这个新元素。"},{"id":"dsa13003-pl-P4604219","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"若有一个双端队列，初始为空，且两端均可进行入队和出队操作。若依次进行以下操作：左端入队1，右端入队2，左端出队，右端入队3，则此时队列中的元素顺序为（ ）。","opts":["A. 2，3","B. 3，2","C. 1，2，3","D. 3，1，2"],"ans":0,"explain":"根据双端队列的性质，左端入队1后，队列为1；右端入队2后，队列为1，2；左端出队后，队列为2；右端入队3后，队列为2，3。"},{"id":"dsa13003-pl-P4604220","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"在双端队列中，若一端仅允许入队，另一端既允许入队也允许出队，则这种双端队列称为（ ）。","opts":["A. 输入受限的双端队列","B. 输出受限的双端队列","C. 双向队列","D. 双向栈"],"ans":0,"explain":"对双端队列两端的操作加以限制，如其中一端仅允许入队，另一端既允许入队，又允许出队，得到的是输入受限的双端队列。"},{"id":"dsa13003-pl-P4604221","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"使用两个栈S和T来模拟队列时，如果栈S已满但栈T为空，此时尝试入队一个新元素，应该（）去处理。","opts":["A. 直接将新元素入栈到S中，因为T为空。","B. 无法入队，因为S已满。","C. 将S中所有元素出栈并入栈到T中，然后将新元素入栈到S中。","D. 无需处理，因为T为空，可以直接使用T。"],"ans":2,"explain":"元素e入队的过程是：若栈S不满，则元素e入栈到S中；否则，若栈T为空，则将栈S中的所有元素出栈并入栈到T中，然后元素e入栈到S中。"},{"id":"dsa13003-pl-P4604222","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"使用两个队列P和Q来模拟栈时，如果队列P已满，此时尝试入栈一个新元素，应该（）去处理。","opts":["A. 直接将新元素入队到P中，因为Q为空。","B. 无法入栈，因为P已满。","C. 将P中所有元素出队并入队到Q中，然后将新元素入队到P中。","D. 无需处理，因为Q为空，可以直接使用Q。"],"ans":1,"explain":"当元素e入栈S时，若队列P不满，则e进入队列P中，否则队列P已满，则表示栈满，入栈失败。"},{"id":"dsa13003-pl-P4604223","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"在检查括号匹配时，如果遇到一个闭括号但栈为空，这通常表示（）。","opts":["A. 表达式是平衡的","B. 表达式中缺少与该闭括号对应的开括号","C. 表达式中有多余的开括号","D. 表达式中有交错的括号"],"ans":1,"explain":"扫描到闭括号时发现栈为空，说明缺少与此闭括号对应的开括号。"},{"id":"dsa13003-pl-P4604224","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"在将中缀表达式转换为后缀表达式的过程中，如果栈内运算符的优先级低于栈外运算符的优先级，应该（）处理。","opts":["A. 栈内运算符出栈，栈外运算符入栈","B. 栈内运算符保持不变，栈外运算符入栈","C. 栈内运算符出栈，栈外运算符保持不变","D. 栈内运算符和栈外运算符都保持不变"],"ans":1,"explain":"若栈外运算符的优先级高于栈内运算符的优先级，则栈外运算符入栈，继续读入表达式的下一个符号。"},{"id":"dsa13003-pl-P4604225","type":"sc","tier":"基础","conf":"adapt","chap":"第3-4章","q":"在输出杨辉三角形的算法中，每行数据的生成依赖于（）。","opts":["A. 前一行","B. 后一行","C. 当前行","D. 任意一行"],"ans":0,"explain":"只要保存了前一行的数据，就可以按规律生成后一行的数据."},{"id":"dsa13003-pl-P4604368","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"请简述顺序表和链表在哪些方面存在显著的差异，并分别给出应用场景的示例。","opts":[],"ans":null,"explain":"1.存储空间分配：<br/>顺序表：需要预先分配一块连续的内存空间，且大小固定。当元素个数增加且超过预分配的空间时，需要重新分配更大的空间并进行数据迁移。<br/>链表：动态分配内存空间，每个节点包含数据元素和指向下一个节点的指针。链表的大小可以随元素个数的增加而动态变化。<br/>应用场景：当数据规模较大且元素个数频繁变化时，链表更加适合，因为它可以动态调整空间大小，避免频繁的数据迁移。<br/>2.访问效率：<br/>顺序表：支持随机访问，即可以通过索引直接访问任意位置的元素，时间复杂度为O(1)。<br/>链表：不支持随机访问，访问元素时只能从头节点开始逐个遍历，时间复杂度为O(n)。<br/>应用场景：当需要频繁进行随机访问操作时，如查找、更新特定位置的元素，顺序表更加高效。<br/>3.插入和删除操作：<br/>顺序表：在插入或删除元素时，需要移动插入或删除位置之后的所有元素，时间复杂度为O(n)。<br/>链表：在已知插入或删除位置的前提下，可以在O(1)时间内完成插入或删除操作，只需修改指针即可。<br/>应用场景：当需要频繁在链表的不同位置进行插入和删除操作时，链表更加灵活和高效。"},{"id":"dsa13003-pl-P4604369","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"请简述栈的入栈和出栈操作对栈顶元素的影响，并给出栈顶元素变化的规律。","opts":[],"ans":null,"explain":"1.入栈操作：<br/>当一个元素入栈时，该元素被放置在栈顶，成为新的栈顶元素。<br/>栈的长度增加1。<br/>栈顶元素变化为刚入栈的元素。<br/>2.出栈操作：<br/>当执行出栈操作时，栈顶元素被移除，其下一个元素（如果存在）成为新的栈顶元素。<br/>栈的长度减少1。<br/>如果栈原本为空，则出栈操作可能引发错误或异常。<br/>3.栈顶元素变化的规律：<br/>入栈时，栈顶元素变为新入栈的元素。<br/>出栈时，栈顶元素被移除，下一个元素（如果有）成为新的栈顶元素；如果栈为空，则没有栈顶元素。<br/>栈顶元素是栈中最后入栈的元素，也是最先可能被出栈的元素。"},{"id":"dsa13003-pl-P4604370","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"简述循环队列和链式队列的主要区别。","opts":[],"ans":null,"explain":"1.存储方式：循环队列使用一维数组存储元素，而链式队列使用单链表存储元素。<br/>2.指针/下标：循环队列使用front和rear两个整型变量（下标）来指示队头和队尾的位置，链式队列则使用两个指针（front和rear）来指向队头和队尾的结点。<br/>3.扩容：循环队列在数组大小确定后，其容量是固定的，无法动态扩容；链式队列则可以通过动态分配内存来实现扩容。<br/>4.判空和判满：循环队列需要额外的逻辑（如保留一个空闲位置或使用标记变量）来判断队列是否为空或满；链式队列则相对简单，队头指针和队尾指针都为NULL时队列为空，通常不考虑队列满的情况（除非内存耗尽）。"},{"id":"dsa13003-pl-P4604371","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"请简述双端队列与普通队列的主要区别，并举例说明在何种情况下使用双端队列更为合适。","opts":[],"ans":null,"explain":"1.主要区别：操作灵活性不同。<br/>2.使用场景：灵活处理进出顺序。"},{"id":"dsa13003-pl-P4604372","type":"sa","tier":"创新","conf":"adapt","chap":"第3-4章","q":"请简述使用栈检查括号匹配算法的基本步骤。","opts":[],"ans":null,"explain":"1.初始化一个空栈。<br/>2.逐个读取输入的括号字符。<br/>3.如果遇到开括号（&#039;(&#039;、&#039;[&#039;、&#039;{&#039;），则将其压入栈中。<br/>4.如果遇到闭括号（&#039;)&#039;、&#039;]&#039;、&#039;}&#039;），则检查栈是否为空以及栈顶的开括号是否与当前闭括号匹配。<br/>    如果栈为空或栈顶开括号与当前闭括号不匹配，则表达式不平衡。<br/>    如果匹配，则从栈中弹出栈顶的开括号。<br/>5.重复步骤2-4，直到处理完所有输入的括号字符。<br/>6.如果栈为空，则表达式平衡；否则，表达式不平衡（因为有多余的开括号）。"},{"id":"dsa13003-pl-P4604323","type":"calc","tier":"创新","conf":"adapt","chap":"第1-2章","q":"请简述在引入空闲单元链表后，如何在单链表中插入一个新结点的过程。","opts":[],"ans":null,"explain":"1.检查freelist是否为空。<br/>2.若非空，取结点并插入。<br/>3.若为空，malloc新结点并插入。"},{"id":"dsa13003-pl-P4604324","type":"calc","tier":"创新","conf":"adapt","chap":"第1-2章","q":"设计一个算法，用于在静态链表中查找一个特定的元素值x，并返回该元素在数组中的下标。如果元素不存在，则返回-1。","opts":[],"ans":null,"explain":"int findElementInStaticList(int A[], int maxSize, int x) {  <br/>    if (A[0].data == 0) {  <br/>        // 链表为空  <br/>        return -1;  <br/>    }  <br/>  <br/>    int currentIndex = A[0].next; // 从链表的第一个实际元素开始  <br/>    while (currentIndex != -1) {  <br/>        if (A[currentIndex].data == x) {  <br/>            // 找到元素  <br/>            return currentIndex;  <br/>        }  <br/>        currentIndex = A[currentIndex].next; // 移动到下一个元素  <br/>    }  <br/>  <br/>    // 遍历完链表未找到元素  <br/>    return -1;  <br/>}"},{"id":"dsa13003-pl-P4604325","type":"calc","tier":"创新","conf":"adapt","chap":"第3-4章","q":"阅读以下链式栈的入栈操作实现代码，并回答问题。 typedef struct StackNode { ElementType data; struct StackNode *next; } StackNode, *LinkStackPtr; typedef struct { LinkStackPtr top; int maxSize; } LinkStack; // 入栈操作 int Push(LinkStack *S, ElementType e) { LinkStackPtr s = (LinkStackPtr)malloc(sizeof(StackNode)); if (!s) { // 内存分配失败 return 0; } s-&gt;data = e; s-&gt;next = S-&gt;top; // 新结点指向原栈顶 S-&gt;top = s; // 栈顶指针指向新结点 return 1; } 1.代码中malloc函数的作用是什么？ 2.s-&gt;next = S-&gt;top;这行代码的作用是什么？ 3.简述入栈操作的时间复杂度。","opts":[],"ans":null,"explain":"1.malloc函数用于动态分配内存空间，这里用于为新的栈结点分配内存。<br/>2.s-&gt;next = S-&gt;top;这行代码的作用是将新创建的结点s的next指针指向原来的栈顶元素，即实现新结点插入到栈顶的操作。<br/>3.入栈操作的时间复杂度是O(1)，因为无论栈中元素数量多少，入栈操作都只需要常数时间即可完成，主要是为新结点分配内存和修改栈顶指针。"},{"id":"dsa13003-pl-P4604326","type":"calc","tier":"创新","conf":"adapt","chap":"第3-4章","q":"阅读以下关于链式队列入队操作的伪代码，并简述其主要步骤。 function EnQueue(queue, element): if queue is empty: create a new node with element set queue.front and queue.rear to the new node else: create a new node with element queue.rear.next = new node queue.rear = new node","opts":[],"ans":null,"explain":"这段伪代码实现了链式队列的入队操作。首先检查队列是否为空，如果为空，则创建一个新结点，并将队头指针和队尾指针都指向这个新结点，因为此时队列中只有一个结点，它既是队头也是队尾。如果队列不为空，则同样创建一个新结点，但是这次是将新结点插入到当前队尾结点的后面，并更新队尾指针指向这个新结点，从而实现了在队尾插入新元素的操作。\n1.检查队列是否为空。<br/>2.如果队列为空，则创建一个新结点，并将该结点同时设置为队头结点和队尾结点。<br/>3.如果队列不为空，则创建一个新结点，并将该结点插入到队尾结点的后面，然后更新队尾指针指向新结点。"},{"id":"dsa13003-pl-P4604327","type":"calc","tier":"创新","conf":"adapt","chap":"第3-4章","q":"请简述使用两个队列P和Q模拟栈时，出栈操作的主要步骤。","opts":[],"ans":null,"explain":"1.判断队列P是否为空，若为空则栈为空，出栈失败。<br/>2.若P不为空，则将P中除最后一个元素外的所有元素依次出队并入队到Q中。<br/>3.将P中剩余的最后一个元素出队，作为出栈元素。<br/>4.（可选）如果希望保持P作为主队列，则将Q中所有元素出队并入队到P中。"},{"id":"dsa13003-pl-P4604328","type":"calc","tier":"创新","conf":"adapt","chap":"第3-4章","q":"请简述将中缀表达式转换为后缀表达式的算法步骤。","opts":[],"ans":null,"explain":"1.初始化一个运算符栈和一个空的后缀表达式列表。<br/>2.从左至右扫描中缀表达式的每个字符。<br/>    如果是操作数，则直接将其添加到后缀表达式列表中。<br/>    如果是运算符，则与栈顶运算符进行比较：<br/>        如果栈为空或栈顶是左括号“(”，则将当前运算符入栈。<br/>        如果栈顶运算符的优先级高于当前运算符，则将栈顶运算符弹出并添加到后缀表达式列表中，重复此过程直到栈为空或栈顶运算符优先级低于或等于当前运算符。<br/>        将当前运算符入栈。<br/>    如果是左括号“(”，则将其入栈。<br/>    如果是右括号“)”，则依次弹出栈顶运算符并添加到后缀表达式列表中，直到遇到左括号“(”，将左括号从栈中弹出（但不添加到后缀表达式列表中）。<br/>3.扫描完中缀表达式后，将栈中剩余的运算符依次弹出并添加到后缀表达式列表中。"},{"id":"dsa13003-pl-P4604329","type":"calc","tier":"创新","conf":"adapt","chap":"第3-4章","q":"设计一个简单的算法，用于输出杨辉三角形的前n行（n为正整数）。","opts":[],"ans":null,"explain":"1.初始化：创建一个列表（或数组）用于存储当前行的数据，初始时只包含1（即第一行）。<br/>2.循环生成：从第二行开始，使用循环生成接下来的n-1行。<br/>3.计算并添加：对于每一行，除了首尾添加1外，中间的每个数通过取上一行对应位置及其前一个位置的数之和得到，并将这些数添加到当前行列表中。<br/>4.输出：在每次循环结束时，输出当前行的数据（注意格式化，如每行数据之间用空格分隔）。<br/>5.结束：当生成了n行后，结束算法。"},{"id":"dsa13003-pl-P4604414","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"在双向链表中，每个结点除了存储数据元素外，还需要存储__1__个指针。","opts":[],"ans":["两（或2）"],"explain":"双向链表中的每个结点除了存储数据元素外，还需要存储两个指针：一个指向前一个结点（prev），另一个指向后一个结点（next）。这使得双向链表在向前和向后遍历方面都比单链表更加灵活。\n参考答案: A.两（或2）"},{"id":"dsa13003-pl-P4604415","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"在引入空闲单元链表freelist后，当需要从链表中删除一个结点时，应将这个结__1__到freelist中。","opts":[],"ans":["插入"],"explain":"当从链表L中删除一个结点时，为了避免立即释放该结点的内存空间，可以将其插入到空闲单元链表freelist中，以便后续在需要时可以重用该结点，从而减少内存分配和释放的开销。\n参考答案: A.插入"},{"id":"dsa13003-pl-P4604416","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"在静态链表中，用于标识空闲单元的特殊标记通常可以通过设置该单元的next字段为__1__来实现。","opts":[],"ans":["-1"],"explain":"在静态链表中，为了区分空闲单元和已使用单元，通常会将空闲单元的next字段设置为一个特殊值，如-1，来表示该单元当前是空闲的。\n参考答案: A.-1"},{"id":"dsa13003-pl-P4604417","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"在不知道单链表长度的情况下，为了查找单链表中倒数第k个结点，需要设置两个指针front和rear，初始时让front指针先前进__1__步，然后两个指针同步前进，直到front到达链表末尾。","opts":[],"ans":["k"],"explain":"为了查找单链表中倒数第k个结点，在不知道链表长度的情况下，可以设置两个指针front和rear。初始时，让front指针先前进k步，作为“排头兵”，这样front和rear之间就相隔了k个结点。然后两个指针同步前进，直到front到达链表末尾，此时rear就指向了倒数第k个结点。\n参考答案: A.k"},{"id":"dsa13003-pl-P4604418","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"在查找单链表中间结点的算法中，若使用两个指针front和rear，其中front指针每次移动__1__步，rear指针每次移动__2__步，当front指针到达链表末尾时，rear指针即指向链表的中间结点（或当结点数为偶数时，前一个中间结点）。","opts":[],"ans":["两B.一"],"explain":"为了查找单链表的中间结点（或当结点数为偶数时，前一个中间结点），需要使用两个指针front和rear。其中，front指针作为“排头兵”，每次移动两步，而rear指针则每次移动一步。当front指针到达链表末尾时，rear指针即指向链表的中间结点（或当结点数为偶数时，前一个中间结点）。\n参考答案: A.两B.一"},{"id":"dsa13003-pl-P4604419","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"在单链表逆置的算法中，如果left、middle和right分别指向链表中相邻的三个结点，那么在逆置过程中，首先需要将middle的next指针指向__1__，然后更新三个指针的位置，以便对下一个结点进行相同的操作。","opts":[],"ans":["left"],"explain":"在单链表逆置的算法中，我们需要将每个结点的next指针反向，即让原来指向后继结点的指针指向前驱结点。当left、middle和right分别指向链表中相邻的三个结点时，我们首先需要将middle的next指针指向left（即原来middle的前驱结点），这样就完成了middle和left之间链接的反向。\n参考答案: A.left"},{"id":"dsa13003-pl-P4604420","type":"fill","tier":"拔高","conf":"adapt","chap":"第3-4章","q":"栈是一种具有__1__特性的线性表，其操作仅能在栈顶进行。","opts":[],"ans":["后进先出（LIFO）"],"explain":"栈是一种限定仅在一端进行插入和删除的线性表，这端称为栈顶，另一端称为栈底。栈具有后进先出的特性，即最后入栈的元素会最先出栈。\n参考答案: A.后进先出（LIFO）"},{"id":"dsa13003-pl-P4604421","type":"fill","tier":"拔高","conf":"adapt","chap":"第3-4章","q":"链式栈中，栈顶元素是通过__1__来访问的。","opts":[],"ans":["栈顶指针（或头指针）"],"explain":"在链式栈中，栈顶元素是通过栈顶指针（或称为头指针）来访问的。链式栈可以看作是一个仅在表头位置进行操作的单链表，栈顶指针指向链表的第一个结点，即栈顶元素。\n参考答案: A.栈顶指针（或头指针）"},{"id":"dsa13003-pl-P4604422","type":"fill","tier":"拔高","conf":"adapt","chap":"第3-4章","q":"在程序设计中，处理一系列的函数调用和递归调用时，系统内部会开辟一个称为__1__的数据结构来保存函数在调用过程中所需的信息。","opts":[],"ans":["函数调用栈"],"explain":"系统内部会开辟一个函数调用栈用来保存函数在调用过程中所需的一些信息。\n参考答案: A.函数调用栈"},{"id":"dsa13003-pl-P4604423","type":"fill","tier":"拔高","conf":"adapt","chap":"第3-4章","q":"队列是一种特殊的线性表，它只能在表的一端进行插入操作，称为__1__；在另一端进行删除操作，称为（）。","opts":[],"ans":["入队","出队"],"explain":"在队尾插入元素称为入队，从队头删除元素称为出队。\n参考答案: A.入队；出队"},{"id":"dsa13003-pl-P4604424","type":"fill","tier":"拔高","conf":"adapt","chap":"第3-4章","q":"在链式队列中，若队列为空，则队头指针front和队尾指针rear的值都为__1__。","opts":[],"ans":["NULL"],"explain":"在空链式队列中，队头指针和队尾指针都为NULL。\n参考答案: A.NULL"},{"id":"dsa13003-pl-P4604425","type":"fill","tier":"拔高","conf":"adapt","chap":"第3-4章","q":"在双端队列中，若一端进行入队操作，另一端进行出队操作，则此时双端队列的操作特性与__1__类似。","opts":[],"ans":["队列"],"explain":"当将一端的入队操作及另一端的出队操作看作一对操作时，双端队列与普通队列是一样的。\n参考答案: A.队列"},{"id":"dsa13003-pl-P4604426","type":"fill","tier":"拔高","conf":"adapt","chap":"第3-4章","q":"使用两个栈S和T模拟队列时，队列为空的条件是__1__。","opts":[],"ans":["S","T均为空"],"explain":"什么状态表示队列为空呢？显然，当S和T均为空时，队列为空。\n参考答案: A.S和T均为空"},{"id":"dsa13003-pl-P4604427","type":"fill","tier":"拔高","conf":"adapt","chap":"第3-4章","q":"使用栈检查括号匹配时，遇到开括号需执行的操作是__1__。","opts":[],"ans":["入栈"],"explain":"在读入的符号是开括号时，入栈。\n参考答案: A.入栈"},{"id":"dsa13003-pl-P4604428","type":"fill","tier":"拔高","conf":"adapt","chap":"第3-4章","q":"后缀表达式中，运算符出现在其两个操作数的__1__。","opts":[],"ans":["后面"],"explain":"运算符出现在其两个操作数之后的表达式是后缀表达式。\n参考答案: A.后面"},{"id":"dsa13003-pl-P4604429","type":"fill","tier":"拔高","conf":"adapt","chap":"第3-4章","q":"在计算后缀表达式时，为了减少对空栈的判定，初始时在栈底放置一个特殊值，该特殊值通常用__1__符号表示。","opts":[],"ans":["“#” 或 特殊符号"],"explain":"为了减少对空栈的判定，初始时在栈底放置一个特殊值-65536，例3-16中以“#”表示。\n参考答案: A.“#” 或 特殊符号"},{"id":"dsa13003-pl-P4604430","type":"fill","tier":"拔高","conf":"adapt","chap":"第3-4章","q":"杨辉三角形中，除了每行的首尾为1外，其余每个数是它__1__两个数之和。","opts":[],"ans":["上一行左上","右上"],"explain":"中间的每个数都是其上一行中位于其左上、右上的两个数之和.\n参考答案: A.上一行左上和右上"},{"id":"dsa13003-pl-P4604183","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在计算机科学中，下列（）不是数据元素可以细分的最小单位。","opts":["A. 字符","B. 整数","C. 数据项","D. 1位（bit）"],"ans":1,"explain":"构成数据的基本单位称为数据元素，数据元素还可以细分为数据项。同时，数据元素可大可小，小到可以是一个字符，甚至是计算机中的1位（bit）。整数并不是数据元素的最小不可分割单位，而是数据项的一种可能值。"},{"id":"dsa13003-pl-P4604184","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在数据结构中，使用哈希表进行元素存储时，主要依赖的存储方法是（）。","opts":["A. 顺序存储方法","B. 链式存储方法","C. 索引存储方法","D. 散列（哈希）存储方法"],"ans":3,"explain":"散列存储方法是一种特殊方法，它根据数据元素的关键字计算出该元素的物理存储位置。通常，使用称为散列表的一维数组作为保存元素的结构。"},{"id":"dsa13003-pl-P4604185","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在抽象数据类型（ADT）的定义中，不包含以下（）内容。","opts":["A. 类型的名字","B. 操作的实现细节","C. 操作的名字","D. 操作的输入输出描述"],"ans":1,"explain":"除了程序设计语言中提供的基本类型以外，还可以定义抽象意义下的类型，并为该类型定义一组相关的操作。这样定义的数据类型称为抽象数据类型（ADT）。抽象数据类型的定义包括类型的名字及对各个操作的刻画，也就是要明确“做什么”。对于每个操作，要规定操作的名字、操作执行的前提条件、输入和输出分别是什么等。每个操作通常表示为一个函数或方法。 “抽象数据类型”是相对于程序设计语言中的“基本类型”来说的。抽象数据类型通常都是程序设计语言中没有提供的类型。在给出抽象数据类型的定义时，尚未明确所定义类型的数据元素的存储方式，当然也没有给出各操作的实现细节。在实现环节，才会给出所定义的类型中涉及的数据元素使用哪种方式保存及如何保存。有了存储结构，才能具体实现各操作，也就是实现“如何做”。"},{"id":"dsa13003-pl-P4604186","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"下列（）概念与“抽象数据类型”的“抽象”含义最为接近。","opts":["A. 程序的执行效率","B. 数据元素的存储方式","C. 数据的逻辑结构","D. 函数的返回值类型"],"ans":2,"explain":"抽象数据类型强调的是数据的逻辑结构及其操作，而不涉及数据元素的物理存储方式或执行效率等具体实现细节。"},{"id":"dsa13003-pl-P4604187","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"以下（）不是算法的基本特性。","opts":["A. 输入","B. 输出","C. 无限性","D. 确定性"],"ans":2,"explain":"算法必须满足的五个重要特性包括输入、输出、有穷性、确定性和可行性。"},{"id":"dsa13003-pl-P4604188","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"以下（）描述方式通常用于算法的初步设计或解释，而不直接用于计算机执行。","opts":["A. 机器语言","B. 伪代码","C. 汇编语言","D. 高级程序设计语言"],"ans":1,"explain":"算法描述一个问题的求解过程，由一系列解决问题的清晰指令构成。这些指令可以使用自然语言表示，也可以使用计算机程序设计语言表示，甚至可以混合使用自然语言与计算机程序设计语言来描述。C语言与自然语言的混合有时称为类C语言，这样描述的算法称为伪代码。"},{"id":"dsa13003-pl-P4604189","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"以下（）正确地描述了算法的时间复杂度概念。","opts":["A. 算法的时间复杂度是算法执行过程中所需时间的精确值。","B. 算法的时间复杂度是通过测量程序运行的绝对时间来确定的。","C. 算法的时间复杂度是通过计算算法执行过程中需要执行的语句总数来评估的。","D. 算法的时间复杂度是算法执行时间随问题规模增长的渐近变化规律。"],"ans":3,"explain":"算法的时间复杂度并不是精确的执行时间，也不是通过测量程序运行的绝对时间来确定的，而是通过问题规模的增长来评估算法执行时间的渐近变化规律。"},{"id":"dsa13003-pl-P4604190","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在算法复杂度分析中，大O表示法（O-notation）主要用于描述算法的（）。","opts":["A. 最优时间复杂度","B. 平均时间复杂度","C. 最坏时间复杂度","D. 空间复杂度"],"ans":2,"explain":"在算法复杂度分析中，大O表示法（O-notation）通常用于描述算法的最坏时间复杂度，因为它提供了算法执行时间的一个上界。虽然最优时间复杂度和平均时间复杂度也很重要，但大O表示法更侧重于最坏情况的分析。"},{"id":"dsa13003-pl-P4604191","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"斐波那契数列F(n)（n≥1）的定义中，用于计算第n项值的递推关系是（）。","opts":["A. F(n) = F(n-1) + F(n-2)","B. F(n) = F(n-1) * F(n-2)","C. F(n) = F(n-1) - F(n-2)","D. F(n) = 2 * F(n-1)"],"ans":0,"explain":"式（1－1）的最后一行给出的是递推关系，使用斐波那契数列的第n-1项和第n-2项，可以计算出数列的第n项。"},{"id":"dsa13003-pl-P4604192","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"迭代法求解两个正整数最大公约数时，迭代过程终止的条件是（）。","opts":["A. 当m和n相等时","B. 当m或n达到某个预设的阈值时","C. 当m为0时","D. 当迭代次数达到预设值时"],"ans":2,"explain":"当m为0时，迭代过程终止。"},{"id":"dsa13003-pl-P4604193","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在递归定义阶乘函数fact(n)时，递归出口是（）。","opts":["A. n &gt; 0","B. n &gt;= 0","C. n == 0","D. n != 0"],"ans":2,"explain":"当n为0时，结束递归，这是递归出口。"},{"id":"dsa13003-pl-P4604194","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在线性表L = (a₀, a₁, a₂, ..., an-1)中，元素a₁的直接前驱是（）。","opts":["A. a₀","B. a₂","C. 不存在","D. a-1"],"ans":0,"explain":"对于元素ai（1≤i≤n-1），元素aj（0≤j&lt;i）称为ai的前驱，其中元素ai-1称为ai的直接前驱。"},{"id":"dsa13003-pl-P4604195","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"以下（）描述不符合线性表的特点。","opts":["A. 线性表中所有元素类型相同","B. 线性表元素个数是无限的","C. 线性表元素之间有次序关系","D. 线性表可以是有序表或无序表"],"ans":1,"explain":"线性表是由同类型数据元素构成的有限序列。"},{"id":"dsa13003-pl-P4604196","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在线性表LinearList的抽象数据类型中，insertList操作成功执行后，通常返回（）值来表示操作成功。","opts":["A. 插入的元素值","B. 插入元素后的线性表长度","C. 1","D. 插入元素的位置"],"ans":2,"explain":"initList、clear、insertList、removeList、setValue、getValue等操作的返回值表示操作是否已正确执行。在这种情况下，通常1代表执行成功，0或-1代表执行时遇到了某些问题，比如参数值不正确。"},{"id":"dsa13003-pl-P4604197","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在线性表LinearList中，如果find操作返回-1，这表示（）。","opts":["A. 线性表已满","B. 线性表为空","C. 查找的元素不存在于线性表中","D. 查找的元素是线性表的最后一个元素"],"ans":2,"explain":"find返回的是要查找的元素x在表中第一次出现的位置，如果表中不包含x，则返回-1。"},{"id":"dsa13003-pl-P4604198","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"顺序表是线性表的一种存储结构，它通过（）数据结构实现。","opts":["A. 链表","B. 栈","C. 队列","D. 数组"],"ans":3,"explain":"顺序存储使用一组连续的存储单元依次存储各个元素。在C语言中，一维数组是顺序存储的连续存储空间，所以线性表的顺序存储结构就是将线性表中的各数据元素，按照其逻辑次序，依次保存到数组中。"},{"id":"dsa13003-pl-P4604199","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在顺序表中，如果要删除第i个元素（0≤i&lt;n，n为顺序表当前长度），则其后继元素需要向前移动（）个位置。","opts":["A. i","B. n-i","C. 1","D. n"],"ans":2,"explain":"在执行‘删除位置i的元素’时，需要将ai后面的元素依次前移一个位置。"},{"id":"dsa13003-pl-P4604200","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在顺序表中，若要在位置i（0≤i≤n，n为当前元素个数）插入一个新元素，并且假设在任何位置插入的概率相等，则平均需要移动的元素个数是（）。","opts":["A. n/2","B. (n-i)","C. (n+1)/2","D. (n-i+1)/2"],"ans":0,"explain":"如果在任何位置进行插入的概率都相等，则插入操作中，移动元素的平均次数N为(n+1)/2 - 1 = n/2。"},{"id":"dsa13003-pl-P4604201","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在单链表中，如果要删除某个结点，首先需要做的是（）。","opts":["A. 找到该结点的前驱结点","B. 找到该结点的后继结点","C. 直接修改该结点的值","D. 释放该结点的内存"],"ans":0,"explain":"在单链表中删除某个结点，首先需要找到该结点的前驱结点，以便修改前驱结点的next指针，使其指向被删除结点的后继结点，从而完成删除操作。"},{"id":"dsa13003-pl-P4604202","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在带头结点的单链表中，若已知当前指针curr指向链表的第i个结点（i &gt; 0，从1开始计数），则要在curr所指结点之前插入一个新结点，其时间复杂度为（ ）。","opts":["A. O(1)","B. O(n)","C. O(log n)","D. 无法确定"],"ans":0,"explain":"在带头结点的单链表中，若已知当前指针curr指向链表的第i个结点（从1开始计数），则要在curr所指结点之前插入一个新结点，实际上只需要修改curr所指结点的前驱结点的next指针，使其指向新结点，然后让新结点的next指针指向curr所指的结点即可。由于当前指针curr已经指向了正确的位置，因此这个操作可以在常数时间内完成，即时间复杂度为O(1)。"},{"id":"dsa13003-pl-P4604203","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在单向循环链表中，如果表尾结点的next指针指向头结点，则关于该链表的以下说法正确的是（）。","opts":["A. 链表中至少有两个结点","B. 链表中只有一个结点","C. 链表为空","D. 无法确定链表中结点的数量"],"ans":0,"explain":"单向循环链表的特性是表尾结点的next指针指回头结点。这个特性只有在链表至少有两个结点时才能成立，因为只有一个结点时，该结点无法同时作为头结点和表尾结点并指向自己。如果链表为空，则没有头结点或数据结点。"},{"id":"dsa13003-pl-P4604204","type":"sc","tier":"基础","conf":"adapt","chap":"第1-2章","q":"在双向链表中，若要在某个非尾结点p之后插入一个新结点s，且保持双向链表的正确性，以下（）操作序列是正确的。","opts":["A. s-&gt;prev = p; p-&gt;next = s; s-&gt;next = p-&gt;next; p-&gt;next-&gt;prev = s;","B. p-&gt;next = s; s-&gt;prev = p; s-&gt;next = p-&gt;next; p-&gt;next-&gt;prev = s;","C. p-&gt;next = s; s-&gt;prev = p-&gt;prev; s-&gt;next = p-&gt;next; p-&gt;next-&gt;prev = s;","D. s-&gt;prev = p; s-&gt;next = p-&gt;next; p-&gt;next = s; p-&gt;prev = s;"],"ans":0,"explain":"在双向链表中插入新结点s到结点p之后，需要确保p的next指针指向s，s的prev指针指向p，同时s的next指针指向p的原始后继结点，并且更新p的原始后继结点的prev指针指向s。"},{"id":"dsa13003-pl-P4604361","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"请比较顺序存储结构和链式存储结构在存储线性表时的优缺点，并给出应用场景示例。","opts":[],"ans":null,"explain":"1.顺序存储结构的优缺点：<br/>优点：<br/>存储密度大；访问速度快；效率较高。<br/>缺点：<br/>在表扩容时需要进行大量的数据移动；效率较低。<br/>应用场景示例：当线性表的长度变化不大，且主要操作是访问元素时，适合使用顺序存储结构，如静态数组的实现。<br/><br/>2.链式存储结构的优缺点：<br/>优点：<br/>存储空间灵活；只需要修改指针，效率高。<br/>缺点：<br/>存储密度较低；访问效率低。<br/>应用场景示例：当线性表的长度变化较大，且主要操作是频繁的插入和删除时，适合使用链式存储结构，如动态链表的实现。同时，链式存储结构也常用于实现栈、队列等数据结构。"},{"id":"dsa13003-pl-P4604362","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"请解释算法的时间复杂度和空间复杂度的概念，并说明它们在算法评价中的重要性。","opts":[],"ans":null,"explain":"1.时间复杂度：运行时间增长速率。<br/>2.空间复杂度：存储空间占用情况。<br/>3.时间重要：影响大数据处理。<br/>4.空间重要：决定内存资源需求。<br/>5.权衡选择：根据需求选算法。"},{"id":"dsa13003-pl-P4604363","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"简述迭代法求解两个正整数最大公约数辗转相除法的关键步骤。","opts":[],"ans":null,"explain":"1.设定初始值<br/>选择两个正整数m和n作为初始值（其中m为被除数，n为除数）。<br/>2.建立迭代关系式<br/>使用m % n（m除以n的余数）作为新的m值，原n值保持不变。<br/>3.迭代执行<br/>重复执行步骤2，直到m为0时停止迭代。<br/>4.输出结果<br/>当迭代停止时，n的值即为两个数的最大公约数。"},{"id":"dsa13003-pl-P4604364","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"编写递归函数时需要注意哪些关键点。","opts":[],"ans":null,"explain":"1.递归出口明确<br/>2.递归变化方向正确<br/>3.参数合理性检查"},{"id":"dsa13003-pl-P4604365","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"简述线性表的三个主要特点。","opts":[],"ans":null,"explain":"1.所有元素类型相同；<br/>2.元素个数有限；<br/>3.元素之间有次序关系。"},{"id":"dsa13003-pl-P4604366","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"简述在顺序表中插入元素和删除元素时的主要步骤和注意事项。","opts":[],"ans":null,"explain":"1.插入元素：<br/>确定插入位置i（0≤i≤n，n为当前元素个数）。<br/>将第i个位置及其后的所有元素依次向后移动一个位置，为新元素腾出空间。<br/>将新元素放到第i个位置。<br/>注意移动元素的次序，应从后向前移动。<br/>2.删除元素：<br/>确定要删除元素的位置i（0≤i&lt;n）。<br/>将第i+1个位置及其后的所有元素依次向前移动一个位置，填补被删除元素的位置。<br/>注意移动元素的次序，应从前往后移动。"},{"id":"dsa13003-pl-P4604367","type":"sa","tier":"创新","conf":"adapt","chap":"第1-2章","q":"简述在单链表中插入新结点的步骤。","opts":[],"ans":null,"explain":"1.创建一个新结点，并将要插入的数据保存到新结点的数据域中。<br/>2.找到新结点应该插入的位置的前驱结点。<br/>3.修改前驱结点的next指针，使其指向新结点。<br/>4.修改新结点的next指针，使其指向原来前驱结点的后继结点。"},{"id":"dsa13003-pl-P4604316","type":"calc","tier":"创新","conf":"adapt","chap":"第1-2章","q":"阅读以下伪代码，描述其主要功能。 算法：学生成绩排序 输入：学生信息列表 students（包含学号、姓名、成绩） 输出：按成绩升序排列的学生信息列表 1. for i from 0 to length(students) - 2 2. for j from 0 to length(students) - i - 2 3. if students[j].成绩 &gt; students[j+1].成绩 4. swap(students[j], students[j+1]) 5. return students","opts":[],"ans":null,"explain":"1.双重循环遍历：该算法通过两层循环遍历学生信息列表，外层循环控制排序的轮数，内层循环负责在每轮中进行实际的比较和交换。 2.比较相邻成绩：在内层循环中，算法比较相邻两个学生的成绩。 3.成绩升序排序：如果前一个学生的成绩大于后一个学生的成绩，则交换这两个学生的信息，以达到按成绩升序排列的目的。最终，算法返回排序后的学生信息列表。\n1.双重循环遍历<br/>2.比较相邻成绩<br/>3.成绩升序排序"},{"id":"dsa13003-pl-P4604317","type":"calc","tier":"创新","conf":"adapt","chap":"第1-2章","q":"分析以下算法的时间复杂度： void sumArray(int arr[], int n) { int sum = 0; for (int i = 0; i &lt; n; i++) { for (int j = 0; j &lt; i; j++) { sum += arr[j]; } } }","opts":[],"ans":null,"explain":"该算法包含两层嵌套循环。外层循环变量i从0遍历到n-1，内层循环变量j从0遍历到i-1。对于外层循环的每一次迭代，内层循环的执行次数是递增的：0, 1, 2, ..., n-1。因此，内层循环总共执行的次数是0 + 1 + 2 + ... + (n-1)，这是一个等差数列的求和问题，其和为n(n-1)/2。加上外层循环和初始化sum的常数时间，算法的总时间复杂度为O(n²)。 这个算法实际上并不是最高效的求数组元素和的方法。它错误地实现了累积和的概念，而不是简单地求所有元素的和。如果目的是求数组的和，更高效的算法应该是单次遍历数组，时间复杂度为O(n)。\nO(n²)"},{"id":"dsa13003-pl-P4604318","type":"calc","tier":"创新","conf":"adapt","chap":"第1-2章","q":"阅读以下函数fibonacci(int a[], int n)的伪代码片段，并回答问题。 void fibonacci(int a[], int n) { if (n &lt;= 0) return; a[0] = 1; if (n == 1) return; a[1] = 1; for (int i = 2; i &lt; n; i++) { a[i] = a[i-1] + a[i-2]; } } 1.该函数通过什么方式实现了斐波那契数列的计算？ 2.当n=5时，数组a中的元素分别是什么？","opts":[],"ans":null,"explain":"1.该函数通过递推法实现了斐波那契数列的计算。它首先初始化数列的前两个值（均为1），然后通过循环，根据斐波那契数列的递推关系（当前项等于前两项之和）计算后续项的值。<br/>2.当n=5时，数组a中的元素分别是1, 1, 2, 3, 5。这是因为根据斐波那契数列的定义和递推关系，前五个数正好是1, 1, 2, 3, 5。"},{"id":"dsa13003-pl-P4604319","type":"calc","tier":"创新","conf":"adapt","chap":"第1-2章","q":"设计一个算法，使用动态规划的思想，但进一步优化以减少空间复杂度，来求解给定整数数组A中的最大子序列和。算法应该仅使用一个变量来保存当前最大子序列和以及另一个变量来记录遍历过程中的最大值。","opts":[],"ans":null,"explain":"这个算法利用了动态规划的思想，但通过仅使用两个变量（current_sum 和 max_sum）来减少空间复杂度。current_sum 用于记录当前子序列的和，它在遍历数组时不断更新，如果加入下一个元素后的和比单独该元素还小（即当前和是负的），则重新以该元素为起点开始计算子序列和。max_sum 用于记录遍历过程中遇到的最大子序列和。通过这两个变量，我们可以在一次遍历中找出最大子序列和，而不需要额外的空间来保存所有子序列的和。\ndef max_subarray_sum(A):  <br/>    if not A:  <br/>        return 0  <br/>      <br/>    current_sum = max_sum = A[0]  <br/>    for num in A[1:]:  <br/>        # 如果当前元素比当前和加上当前元素还要大，说明当前和是负的，应该重新开始计算  <br/>        current_sum = max(num, current_sum + num)  <br/>        # 更新最大和  <br/>        max_sum = max(max_sum, current_sum)  <br/>      <br/>    return max_sum  <br/>  <br/># 示例  <br/>A = [-2, 1, -3, 4, -1, 2, 1, -5, 4]  <br/>print(max_subarray_sum(A))  # 输出: 6"},{"id":"dsa13003-pl-P4604320","type":"calc","tier":"创新","conf":"adapt","chap":"第1-2章","q":"阅读以下关于线性表LinearList的insertList操作的伪代码，并简述其主要步骤。 insertList(L, pos, x): if pos &lt; 0 or pos &gt; length(L): return 0 // 表示位置不合法 if isFull(L): return 0 // 表示线性表已满，无法插入 // 插入操作 for i = length(L); i &gt; pos; i--: L[i] = L[i-1] // 将位置pos及之后的元素后移 L[pos] = x // 在位置pos处插入元素x return 1 // 表示插入成功","opts":[],"ans":null,"explain":"1.检查插入位置是否合法。<br/>2.检查线性表是否已满。<br/>3.从线性表的末尾开始，将位置pos及之后的4.元素向后移动一位，为新元素腾出空间。<br/>5.在位置pos处插入新元素x。<br/>6.返回1，表示插入成功。"},{"id":"dsa13003-pl-P4604321","type":"calc","tier":"创新","conf":"adapt","chap":"第1-2章","q":"阅读以下将顺序表L逆置的算法，并简述其主要步骤。 void reverseList(SeqList* L) { int i, j; int temp; int n = L-&gt;n; // 假设L-&gt;n为顺序表的当前长度 for (i = 0, j = n - 1; i &lt; j; i++, j--) { temp = L-&gt;data[i]; L-&gt;data[i] = L-&gt;data[j]; L-&gt;data[j] = temp; } }","opts":[],"ans":null,"explain":"1.初始化头尾指针i和j。<br/>2.当头指针小于尾指针时，执行循环。<br/>3.交换头尾指针所指向的元素。<br/>4.头指针向后移动，尾指针向前移动。<br/>5.重复步骤2-4，直到头尾指针相遇或交错。"},{"id":"dsa13003-pl-P4604322","type":"calc","tier":"创新","conf":"adapt","chap":"第1-2章","q":"阅读以下关于双向链表删除操作的伪代码，并回答以下问题： function deleteNode(p): if p is None or p-&gt;next is None: return # 节点为空或已经是尾节点，无法删除 p-&gt;prev-&gt;next = p-&gt;next # 将p的前驱节点的next指向p的后继节点 p-&gt;next-&gt;prev = p-&gt;prev # 将p的后继节点的prev指向p的前驱节点 free(p) # 释放p节点所占用的内存 1.伪代码中if语句的条件是什么？ 2.p-&gt;prev-&gt;next = p-&gt;next;这行代码的作用是什么？ 3.free(p);这行代码的目的是什么？","opts":[],"ans":null,"explain":"1.伪代码中if语句的条件是p is None or p-&gt;next is None，用于检查传入的节点p是否为空或者已经是链表的尾节点（尾节点的next为空）。<br/>2.p-&gt;prev-&gt;next = p-&gt;next;这行代码的作用是将p的前驱节点的next指针指向p的后继节点，从而从链表中移除p节点。<br/>3.free(p);这行代码的目的是释放p节点所占用的内存，防止内存泄漏。在C或C++等语言中，动态分配的内存需要手动释放。"},{"id":"dsa13003-pl-P4604398","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"在计算机科学中，__1__是逻辑上相关的、具有物理意义的若干数据项构成的。","opts":[],"ans":["数据元素"],"explain":"逻辑上相关的、具有物理意义的若干数据项构成一个数据元素。\n参考答案: A.数据元素"},{"id":"dsa13003-pl-P4604399","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"在链式存储结构中，用于表示数据元素间逻辑关系的工具是__1__。","opts":[],"ans":["指针"],"explain":"逻辑上相邻的数据元素，不要求其存储的物理位置也相邻，通常借助于程序设计语言中的指针来指示数据元素间的逻辑关系。这样的存储结构称为链式存储结构。\n参考答案: A.指针"},{"id":"dsa13003-pl-P4604400","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"在定义抽象数据类型时，我们通常会明确类型的__1__、操作的__2__、以及操作的__3__。","opts":[],"ans":["名字B.名字C.输入输出描述"],"explain":"抽象数据类型的定义包括类型的名字、各个操作的刻画，其中操作的刻画包括操作的名字、操作执行的前提条件、输入和输出分别是什么等。\n参考答案: A.名字B.名字C.输入输出描述"},{"id":"dsa13003-pl-P4604401","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"算法是一系列指令的描述，它必须满足五个重要特性，包括输入、输出、__1__、确定性和可行性。","opts":[],"ans":["有穷性"],"explain":"1.输入：有0或多个输入值。 2.输出：有1或多个输出值。 3.有穷性：一个算法必须在执行有穷步骤之后结束。 4.确定性：算法的每一个步骤都必5.可行性：算法中要做的运算都是相当基本的、能够精确进行的。\n参考答案: A.有穷性"},{"id":"dsa13003-pl-P4604402","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"算法的空间复杂度通常表示为__1__的一个函数，它衡量的是算法在运行过程中除了初始数据占用的存储空间外，额外需要的存储空间量。","opts":[],"ans":["问题规模"],"explain":"算法的空间复杂度也表示为问题规模的一个函数，用于衡量算法在运行过程中除了初始数据占用的存储空间外，额外需要的存储空间量。\n参考答案: A.问题规模"},{"id":"dsa13003-pl-P4604403","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"贪心法是一种通过每一步选择__1__来达到整体最优解的算法，但可能不是全局最优解。","opts":[],"ans":["局部最优解"],"explain":"贪心法也称贪婪算法，它是一种通过每一步选择局部最优解来达到整体最优解的算法，适用于求某些最优解问题。\n参考答案: A.局部最优解"},{"id":"dsa13003-pl-P4604404","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"分治法求解过程通常分为__1__、求解小问题及小问题解的合并三个阶段。","opts":[],"ans":["划分"],"explain":"一般来说，分治法的求解过程分为三个阶段，即划分、求解小问题及小问题解的合并。\n参考答案: A.划分"},{"id":"dsa13003-pl-P4604405","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"在动态规划求解“最大子序列和”的问题中，如果一个子数组最前面子段的和是负数，则这个子段应该被__1__，以便找到更大的最大子序列和。","opts":[],"ans":["忽略"],"explain":"如果一个子数组最前面子段的和是负数，则这个子段可以被排除。仅当目前子数组的和保持为正时，才持续不断地加入后面的元素，扩大子数组的长度。\n参考答案: A.忽略"},{"id":"dsa13003-pl-P4604406","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"在有序表L = (0, 2, 4, 6, 8)中，元素6的直接后继是__1__。","opts":[],"ans":["8"],"explain":"对于元素ai（0≤i≤n-2），元素aj（i&lt;j≤n-1）称为ai的后继，其中元素ai+1称为ai的直接后继。\n参考答案: A.8"},{"id":"dsa13003-pl-P4604407","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"在线性表LinearList的removeList操作中，当删除位置pos处的元素后，被删除元素的所有后继元素的位置均会__1__。","opts":[],"ans":["减1"],"explain":"删除操作removeList也是类似的，当删除表L中位置pos处的元素后，被删除元素的所有后继元素的位置均减1。\n参考答案: A.减1"},{"id":"dsa13003-pl-P4604408","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"在顺序表中，如果数组的首地址为LOC(a₀)，每个元素占用d个存储单元，则第i个元素（i≥0）的存储首地址是__1__。","opts":[],"ans":["LOC(a₀) + i * d"],"explain":"公式（2－2），“LOC(ai) = LOC(a₀) + (i * d)”，其中LOC(ai)表示第i个元素的存储首地址，LOC(a₀)是数组的首地址，d是每个元素占用的存储单元数。\n参考答案: A.LOC(a₀) + i * d"},{"id":"dsa13003-pl-P4604409","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"顺序表的基本操作中，除了插入和删除操作的时间复杂度为O(n)外，其他如赋值、获取元素值及查找操作的时间复杂度均为__1__。","opts":[],"ans":["O(1)"],"explain":"除了插入和删除操作的时间复杂度均为O(n)外，其他操作的时间复杂度均为O(1)。\n参考答案: A.O(1)"},{"id":"dsa13003-pl-P4604410","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"如果n是偶数，则交换的元素对刚好是n/2。如果n是奇数，则L中间的元素不需要交换，交换的元素对是__1__。","opts":[],"ans":["n","2"],"explain":"如果n是偶数，则交换的元素对刚好是n/2。如果n是奇数，则L中间的元素不需要交换，交换的元素对也是n/2。\n参考答案: A.n/2"},{"id":"dsa13003-pl-P4604411","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"单链表中，若要在位置i处插入一个新结点，首先需要找到__1__的结点。","opts":[],"ans":["位置i-1"],"explain":"在位置i处插入新结点，首先需要找到位置i-1处的结点，即新结点的前驱结点，然后修改这个前驱结点的next指针，使其指向新结点。\n参考答案: A.位置i-1"},{"id":"dsa13003-pl-P4604412","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"单链表中的每个结点除了存储数据元素外，还需要存储一个__1__，用于指向链表中的下一个结点。","opts":[],"ans":["指针"],"explain":"单链表是由一组动态分配的结点形成的链表，每个结点中除了包含数据元素（存储在数据域中）外，还需要包含一个指针（存储在指针域中），该指针用于指向链表中的下一个结点。\n参考答案: A.指针"},{"id":"dsa13003-pl-P4604413","type":"fill","tier":"拔高","conf":"adapt","chap":"第1-2章","q":"在单向循环链表中，表为空的判定条件是 head-&gt;next ==__1__。","opts":[],"ans":["head"],"explain":"在循环链表中，表为空的判定条件是head-&gt;next == head。\n参考答案: A.head"}];
